// Free-tier upsell card: contextual, trial-forward, and dismissable (re-shows after 7 days so it
// nudges without nagging). One per surface only, to stay on the honest-coaching side of the line.
// Opens the existing paywall via the global MPAYWALL, so it works from any screen without prop-drilling.
function PremiumNudge({ db, update, headline, blurb, reason, trackKey, className = '' }) {
  const dm = (db.profile && db.profile.nudgesDismissed) || {};
  const until = dm[trackKey];
  if (until && (Date.now() - until) < 7 * 864e5) return null;
  const open = () => {
    try { window.MPAYWALL && window.MPAYWALL({ type: reason || 'manual' }); } catch (_) {}
    try { window.MTRACK && window.MTRACK('paywall_view', { reason: trackKey }); } catch (_) {}
  };
  const dismiss = (e) => {
    e.stopPropagation();
    update(d => { d.profile = d.profile || {}; d.profile.nudgesDismissed = Object.assign({}, d.profile.nudgesDismissed || {}, { [trackKey]: Date.now() }); });
  };
  return (
    <div onClick={open} className={'pixel-box p-3.5 relative cursor-pointer active:opacity-90 ' + className} style={{ background: 'var(--accent-dim)', borderColor: 'var(--accent)' }}>
      <div className="pf text-[8px] uppercase tracking-widest mb-1.5" style={{ color: 'var(--accent-ink)' }}>Macrosaurus Premium</div>
      <div className="text-sm font-bold mb-1 pr-6">{headline}</div>
      <div className="text-[11px] text-[#8A8A90] leading-snug mb-2.5">{blurb}</div>
      <div className="pf text-[8px] uppercase" style={{ color: 'var(--accent-ink)' }}>Try Premium free ›</div>
      <button onClick={dismiss} className="hit absolute top-1.5 right-1.5 text-[#8A8A90] text-base leading-none px-1.5 py-0.5" aria-label="Not now">×</button>
    </div>
  );
}
// Fills in the day's unscored entries so the quality score covers everything you actually ate, not
// just the foods that happened to arrive with a full nutrition panel. That is recipe ingredients
// (priced by the nutrition database, which carries no saturates, sugars or salt) and anything logged
// before this feature existed. One batched call for the whole day, once, quietly: it never blocks
// the UI, and a failure just leaves those calories reported as unscored rather than guessed at.
// Foods below 5 kcal are skipped, being where the per-100-kcal maths stops meaning anything.
// Only days from the subscription onwards are filled in: food logged as a free user stays as it was
// logged, and a new subscriber's AI allowance is not spent rewriting their history.
const NQ_BACKFILL_MAX = 12;
function useNutrientBackfill(db, update, date, isPremium) {
  const tried = useRef({});
  const premiumSince = (db.profile || {}).premiumSince || null;
  // The trigger is the SET of entries needing work, not the array holding them. update() deep-clones
  // state, so db.log_entries has a fresh identity after every change anywhere in the app; keying the
  // effect on that identity made it restart on every unrelated write.
  const pending = E.pendingNqIds(db.log_entries, date);
  useEffect(() => {
    if (!isPremium || !premiumSince || date < premiumSince) return;
    const todo = (db.log_entries || []).filter(e =>
      e.date === date && !e.nq && !e.is_alcohol
      && ((e.computed_macros || {}).kcal || 0) >= 5
      && !tried.current[e.id]);
    if (!todo.length) return;
    const batch = todo.slice(0, NQ_BACKFILL_MAX);
    // Marked before the call, so a refusal or an error is not retried on every render.
    batch.forEach(e => { tried.current[e.id] = true; });
    (async () => {
      try {
        const out = await aiEstimateNutrientsBatch(batch.map(e => ({
          name: e.name, grams: +e.amount > 0 && e.unit === 'g' ? +e.amount : 0, macros: e.computed_macros,
        })));
        const patch = {};
        batch.forEach((e, i) => {
          const x = out[i]; if (!x) return;
          const nq = E.ndPer100kcal(e.computed_macros,
            Object.assign({}, x, { grams: +e.amount > 0 && e.unit === 'g' ? +e.amount : 0 }));
          if (nq) { nq.est = true; patch[e.id] = nq; }
        });
        if (!Object.keys(patch).length) return;
        // Deliberately NOT guarded by an "is this effect still current" flag. It used to be, and that
        // is what stopped this working at all: the answer came back, an unrelated state write had
        // already torn the effect down, and a call we had paid for was binned. The write below is
        // idempotent (it only fills entries that are still unscored), so applying it late is always
        // better than throwing it away.
        update(d => { (d.log_entries || []).forEach(e => { if (patch[e.id] && !e.nq) e.nq = patch[e.id]; }); });
      } catch (e) {
        // Leave them unscored (the card says so honestly), but do not leave it unreported: this is
        // the call that quietly stops a paying user's day from ever being scored.
        try { window.MTRACK && MTRACK('density_backfill_failed', { items: batch.length, message: String((e && e.message) || e).slice(0, 120) }); } catch (_) {}
      }
    })();
  }, [pending, date, isPremium, premiumSince]);
}
function Dashboard({ db, update, onCheckIn, onReview, onWeigh, setView, onQuickAdd, showToast, onOpenRecipe, onOpenFridge, onOpenPlay, isPremium, aiCalls }) {
  const [mode, setMode] = useState('remaining'); // Left/Eaten lens on the hero macro card
  const [showCarry, setShowCarry] = useState(false);
  const [readyOpen, setReadyOpen] = useState(false); // the buddy's full morning-read sheet, opened from the habitat
  const [recapOpen, setRecapOpen] = useState(false); // the buddy's weekly-recap sheet, opened from the habitat
  const [densityHelp, setDensityHelp] = useState(false); // the Density Score explainer, opened from the macro card
  const today = Store.todayISO();
  const et = effectiveTarget(db, today); if (!et) return null;
  const todayTot = sumMacros(entriesOn(db, today));
  useNutrientBackfill(db, update, today, isPremium);
  const last30 = Array.from({ length: 30 }, (_, i) => shiftISO(today, -(29 - i)));
  const weighSet = new Set(db.weight_entries.map(w => w.date));
  const logSet = new Set(db.log_entries.map(e => e.date));
  const weighDays = last30.map(d => weighSet.has(d)); const logDays = last30.map(d => logSet.has(d));
  const t = currentTargets(db);
  const unit = db.profile.weight_unit;
  const tot = todayTot;
  // Balance: shift today's leftover calories between carbs and fat (protein fixed). Editable right
  // here on Today now, so the Food log no longer needs to repeat the whole macro card.
  const override = (db.day_overrides || {})[today] || { shiftKcal: 0 };
  const setShift = (v) => update(d => { d.day_overrides = Object.assign({}, d.day_overrides || {}, { [today]: { shiftKcal: v } }); });
  const remCarbs = Math.max(0, Math.round(et.eff.carbs_g - todayTot.carbs));
  const remFat = Math.max(0, Math.round(et.eff.fat_g - todayTot.fat));
  // streak: consecutive ACTIVE days (food logged OR weighed in OR a session trained) ending today,
  // with a monthly freeze forgiving one miss.
  const frozenSet = new Set((db.freezes && db.freezes.frozen) || []);
  const trainSet = trainedDates(db);
  const activeSet = new Set([...logSet, ...weighSet, ...trainSet]);
  const streakInfo = computeStreak(activeSet, frozenSet, today, new Set(plannedActiveDates(db)));
  const streak = streakInfo.streak;
  // Reward logging directly: the first log of each day mints a little Amber, so the daily habit visibly
  // pays out (not only fights). Idempotent by ledger id (amber:log:<date>), so it can never double-pay.
  // The signup stake. A brand-new account otherwise reaches the home screen holding nothing: no
  // streak, no dex, and a shop it cannot afford a single thing in. Granted only while the account is
  // genuinely fresh (nothing logged yet), so an established user syncing onto a new device never
  // qualifies, and idempotent by ledger id on top of that.
  useEffect(() => {
    const key = 'amber:welcome';
    if ((db.log_entries || []).length) return;
    if ((db.amber_ledger || []).some(e => e.id === key)) return;
    update(d => { d.amber_ledger = d.amber_ledger || []; if (d.amber_ledger.some(e => e.id === key)) return; d.amber_ledger.push({ id: key, date: today, delta: Game.AMBER_REWARDS.welcome, reason: 'Welcome to Macrosaurus' }); });
  }, [db.log_entries, db.amber_ledger, today]);
  useEffect(() => {
    const key = 'amber:log:' + today;
    if (!(db.log_entries || []).some(e => e.date === today)) return;
    if ((db.amber_ledger || []).some(e => e.id === key)) return;
    update(d => { d.amber_ledger = d.amber_ledger || []; if (d.amber_ledger.some(e => e.id === key)) return; d.amber_ledger.push({ id: key, date: today, delta: Game.AMBER_REWARDS.dailyLog, reason: 'Logged today' }); });
    if (showToast) showToast(((db.buddy && db.buddy.name) || 'Your buddy') + ' found ' + Game.AMBER_REWARDS.dailyLog + ' Amber for today’s log', 'Shop', () => onOpenPlay && onOpenPlay());
  }, [db.log_entries, today]);
  // Trophy award pass: mint any newly-earned achievement trophies (idempotent via game_awards) + toast.
  useEffect(() => {
    const ga = db.game_awards || {};
    const earned = TROPHIES.filter(t => !ga['trophy:' + t.id] && t.earned(db, { streak, isPremium }));
    if (!earned.length) return;
    update(d => { d.game_awards = d.game_awards || {}; earned.forEach(t => { if (!d.game_awards['trophy:' + t.id]) d.game_awards['trophy:' + t.id] = today; }); });
    if (showToast) showToast(earned.length === 1 ? 'Trophy unlocked: ' + earned[0].name : earned.length + ' new trophies unlocked', 'See', () => onOpenPlay && onOpenPlay());
  }, [streak, isPremium, today, db.log_entries, db.buddy && db.buddy.stage, db.fight && db.fight.prestige]);
  // PERSONAL BESTS: say it the moment a finished week beats one. Rewarding improvement rather than
  // attendance is the whole point, and a best nobody is told about is the freeze problem all over
  // again. Gated on a once-per-week marker BEFORE the work, because weeklyBestInputs recomposes a
  // year of daily targets and must not run on every log; the per-measure keys then make the
  // announcement itself idempotent across devices.
  useEffect(() => {
    const lastMon = shiftISO(mondayOf(today), -7);
    const checked = 'bestcheck:' + lastMon;
    if ((db.game_awards || {})[checked]) return;
    const weeks = weeklyBestInputs(db, today);
    const last = weeks.length ? weeks[weeks.length - 1] : null;
    if (!last || last.weekKey !== lastMon) { update(d => { d.game_awards = d.game_awards || {}; d.game_awards[checked] = today; }); return; }
    const beaten = Game.bestsBeaten(Game.personalBests(weeks.slice(0, -1)), last)
      .filter(x => !(db.game_awards || {})['best:' + last.weekKey + ':' + x.key]);
    update(d => {
      d.game_awards = d.game_awards || {};
      d.game_awards[checked] = today;
      beaten.forEach(x => { d.game_awards['best:' + last.weekKey + ':' + x.key] = today; });
    });
    if (beaten.length && showToast) {
      const top = beaten[0];
      showToast('Best week yet · ' + BEST_LABEL[top.key].label.toLowerCase() + ' ' + top.value + '/7', 'Bests', () => onOpenPlay && onOpenPlay());
    }
  }, [db.log_entries, today]);
  // THE COMEBACK. A lapse the monthly freeze could not cover, followed by a day they showed up again.
  // Returning has to pay on the spot: Amber, and a buddy that wakes today rather than in three days.
  // Idempotent by ledger id, like every other grant, so it pays once however many times this renders.
  let lastActiveISO = null;
  activeSet.forEach(d => { if (d < today && (!lastActiveISO || d > lastActiveISO)) lastActiveISO = d; });
  const comeback = Game.comeback(lastActiveISO, today, activeSet.has(today));
  const cameBackToday = !!(db.buddy && db.buddy.wokeISO === today);
  useEffect(() => {
    if (!comeback) return;
    const key = 'amber:comeback:' + today;
    if ((db.amber_ledger || []).some(e => e.id === key)) return;
    update(d => {
      d.amber_ledger = d.amber_ledger || [];
      if (d.amber_ledger.some(e => e.id === key)) return;
      d.amber_ledger.push({ id: key, date: today, delta: comeback.amber, reason: 'Welcome back' });
      d.buddy = d.buddy || { stage: 0 }; d.buddy.wokeISO = today;
    });
    if (showToast) showToast(((db.buddy && db.buddy.name) || 'Your buddy') + ' woke up the moment you came back · +' + comeback.amber + ' Amber', 'Shop', () => onOpenPlay && onOpenPlay());
  }, [comeback && comeback.lapsedDays, today]);
  const freezeAvail = freezeReady(frozenSet, today);
  const newFrozenKey = streakInfo.newFrozen.join(',');
  useEffect(() => {
    if (!newFrozenKey) return;
    const already = new Set((db.freezes && db.freezes.frozen) || []);
    const fresh = newFrozenKey.split(',').filter(x => !already.has(x));
    update(d => { d.freezes = d.freezes || { frozen: [] }; const s = new Set(d.freezes.frozen); newFrozenKey.split(',').forEach(x => s.add(x)); d.freezes.frozen = Array.from(s).sort().slice(-120); });
    // Say it out loud. The freeze has always rescued the streak silently, which meant the single most
    // forgiving thing the app does was the one thing nobody knew about. A rescue nobody notices is
    // not a reward. Only fires for a date not already forgiven, so a re-render cannot re-announce it.
    if (fresh.length && showToast) showToast('Streak freeze used · your ' + streak + '-day streak is safe');
  }, [newFrozenKey]);
  // Per-user catch seeding: mint a stable random salt once, so daily rolls differ between users.
  useEffect(() => {
    if (db.game_salt) return;
    const salt = Game.makeSalt();
    update(d => { if (!d.game_salt) d.game_salt = salt; });
  }, [db.game_salt]);
  // Buddy is a HIGH-WATER mark: the stage never falls back to the egg. After a break it
  // naps at its best-ever stage and wakes after 3 active days. Also track the longest streak.
  const buddyHw = (db.buddy && db.buddy.stage) || 0;
  // `cameBackToday` keeps it awake for the rest of the comeback day, including the renders after the
  // grant lands, so the wake does not flicker back to a nap while the streak is still only 1.
  const buddy = Game.buddyView(buddyHw, streak, !!comeback || cameBackToday);
  const buddyLvl = useMemo(() => buddyLevel(db), [db.log_entries]);
  const bp = buddyProfile(db, streak, buddy, buddyLvl);
  // Hatch trigger: a brand-new account's egg hatches once the core onboarding STAPLES are done - the
  // first real payoff for the habit. These same tasks show inside the buddy habitat so the buddy
  // section is the one place a user sees what to do next. buddy.hatched is set (with the chosen name)
  // when the celebration finishes.
  const [hatching, setHatching] = useState(false);
  const eggIncubating = !!(db.buddy && db.buddy.hatched === false);
  const hatchEt = effectiveTarget(db, today);
  // `eff` carries protein_g, never protein: reading the wrong key left this target undefined, which
  // made the protein staple permanently unticked and meant the egg could never hatch from finishing
  // the staples at all. Matches OnboardingChecklist, which had it right.
  const hatchProteinTgt = hatchEt ? hatchEt.eff.protein_g : 0;
  const hatchTasks = [
    // Creating the account IS the first task, banked before they do anything, so the very first
    // screen a new user sees reads 1/5 rather than 0/4. Nobody should meet this app on a zero.
    { k: 'account', label: 'Created your account', done: true, go: null },
    { k: 'meal', label: 'Log a meal', done: (db.log_entries || []).length > 0, go: () => onQuickAdd(false) },
    { k: 'ai', label: 'Try a Photo or Describe estimate', done: (db.log_entries || []).some(e => e.source === 'ai_estimate' || e.source === 'label'), go: () => onQuickAdd(false) },
    { k: 'protein', label: 'Hit your protein target', done: hatchProteinTgt > 0 && sumMacros(entriesOn(db, today)).protein >= hatchProteinTgt, go: () => onQuickAdd(false) },
    { k: 'weigh', label: 'Add a weigh-in', done: (db.weight_entries || []).length > 0, go: () => onWeigh(true) },
  ];
  const hatchStaplesDone = hatchTasks.every(t => t.done);
  const forceHatchNow = DEMO && new URLSearchParams(window.location.search).has('hatchnow');
  useEffect(() => { if (forceHatchNow || (eggIncubating && hatchStaplesDone)) setHatching(true); }, [eggIncubating, hatchStaplesDone, forceHatchNow]);
  useEffect(() => {
    const longest = (db.records && db.records.longestStreak) || 0;
    if (!buddy.ratchet && streak <= longest) return;
    update(d => {
      d.buddy = d.buddy || { stage: 0 };
      // Seed the celebration marker BEFORE any growth lands, so an account that predates it reads its
      // existing stage as already-celebrated rather than as a fresh multi-stage rise. Game.stageUp
      // treats a null marker as "never fire", which is what keeps the very first seed silent.
      if (d.buddy.stageSeen == null) d.buddy.stageSeen = d.buddy.stage || 0;
      if (buddy.stage > (d.buddy.stage || 0)) d.buddy.stage = buddy.stage;
      d.records = d.records || { longestStreak: 0 };
      if (streak > (d.records.longestStreak || 0)) d.records.longestStreak = streak;
    });
  }, [streak]);
  // Seed the buddy's identity once: hatch date, personality, and the species it's raised from.
  // Additive and idempotent, so returning accounts get an individual without losing anything.
  useEffect(() => {
    const b = db.buddy || {};
    if (b.hatchedISO && b.personality && b.speciesId) return;
    const dates = (db.log_entries || []).map(e => e.date).sort();
    const firstLog = dates[0] || today;
    const spec = buddySpeciesId(db);
    update(d => {
      d.buddy = d.buddy || { stage: 0 };
      if (!d.buddy.hatchedISO) d.buddy.hatchedISO = firstLog;
      if (!d.buddy.personality) d.buddy.personality = personalityFor(d.game_salt || firstLog || 'egg').key;
      if (!d.buddy.speciesId) d.buddy.speciesId = spec;
      if (d.buddy.evoStage == null) d.buddy.evoStage = 0;
    });
  }, [db.buddy, db.log_entries]);
  // Bond-gated evolution (Gen 2 friendship): advance the buddy's form when it has BOTH grown
  // (quality-day level) AND is well cared for (bond hearts). High-water, so a cooled bond never
  // de-evolves it.
  useEffect(() => {
    const b = db.buddy || {};
    const species = CR_BY_ID[b.speciesId]; if (!species || !species.evo || !species.evo.length) return;
    const eligible = Game.buddyEvoStage(buddyLvl, bp.bond.hearts, species.evo.map(e => e.at), EVO_HEART_REQ);
    if (eligible > (b.evoStage || 0)) {
      // Day/night path (Espeon/Umbreon): set once, by the clock at the first evolution.
      const aff = Game.dayNightAffinity(new Date().getHours());
      update(d => { d.buddy = d.buddy || { stage: 0 }; d.buddy.evoStage = eligible; if (!d.buddy.affinity) d.buddy.affinity = aff; });
    }
  }, [buddyLvl, bp.bond.hearts, db.buddy && db.buddy.speciesId]);
  // (The old missed-log/weigh showNudge is superseded by the buddy's always-present coach line.)
  const quote = DINO_QUOTES[new Date(today + 'T00:00:00').getDate() % DINO_QUOTES.length];
  // The buddy's proactive coach line (deterministic for now). Wire the CTA to the right action.
  // The buddy speaks with one voice in the habitat. buddyMessage picks the single top thing to say;
  // here we wire each action string to a handler (the decision stays pure and testable in buddyMessage).
  // A goal milestone waiting to be celebrated (full-screen, below) plus its projection line. Marking it
  // shown persists so it pops exactly once.
  const markMiles = keys => update(d => { d.profile = d.profile || {}; d.profile.milestonesShown = Array.from(new Set([...(d.profile.milestonesShown || []), ...(keys || [])])); });
  const milestone = eggIncubating ? null : goalMilestoneFor(db);
  const milestoneEta = milestone && milestone.kind !== 'reached' ? (goalProjection(db) || {}).text : null;
  // A growth stage reached but not yet celebrated. Queued behind hatch and milestone rather than
  // stacked on top of them, so two full-screen moments never fight; whichever waits shows next render.
  const grewTo = eggIncubating ? null : Game.stageUp((db.buddy || {}).stage, (db.buddy || {}).stageSeen);
  const markGrown = () => update(d => { d.buddy = d.buddy || { stage: 0 }; d.buddy.stageSeen = Math.max(d.buddy.stageSeen || 0, grewTo); });
  // Saving the weight the buddy just asked for: today's entry (overwriting any earlier one), the
  // trend recomputed, and the number read back in a toast so it's obvious where it landed.
  const saveTodayWeight = (kg) => {
    update(d => {
      const t = Store.todayISO(); const ex = d.weight_entries.find(x => x.date === t);
      if (ex) ex.scale_weight = +kg.toFixed(2); else d.weight_entries.push({ id: Store.uid(), date: t, scale_weight: +kg.toFixed(2) });
      recomputeTrend(d);
    });
    showToast && showToast('Logged ' + fmtWeight(kg, unit) + '. Nice one.');
  };
  const msg = (() => {
    // `?demo&quiet` previews the buddy card with nothing on the ladder, which is the common state for
    // a consistent user and the one that is hardest to reach on purpose while working on it.
    if (DEMO && new URLSearchParams(window.location.search).has('quiet')) return null;
    const m = buddyMessage(db, today, streak); if (!m) return null;
    const ackLesson = key => update(d => { d.profile = d.profile || {}; const ls = d.profile.lessonState || { seen: [], lastAck: null }; if ((ls.seen || []).indexOf(key) < 0) ls.seen = (ls.seen || []).concat([key]); ls.lastAck = today; d.profile.lessonState = ls; });
    const ackRead = () => update(d => { d.profile = d.profile || {}; d.profile.readAckDate = today; });
    const ackRecap = () => update(d => { d.profile = d.profile || {}; d.profile.recapAckDate = today; });
    const snoozeKey = k => { if (k) update(d => { d.profile = d.profile || {}; d.profile.nudgesDismissed = Object.assign({}, d.profile.nudgesDismissed || {}, { [k]: Date.now() }); }); };
    const resolve = btn => {
      if (!btn) return null;
      const a = btn.act;
      const onClick =
        a === 'read_open' ? () => { ackRead(); setReadyOpen(true); }
        : a === 'read_ack' ? ackRead
        : a === 'lesson' ? () => ackLesson(btn.lessonKey)
        : a === 'snooze' ? () => snoozeKey(btn.snoozeKey)
        : a === 'review' ? onReview
        : a === 'resume' ? () => onWeigh('resume')
        : a === 'weigh' ? () => onWeigh(true)
        : a === 'checkin' ? onCheckIn
        // These nudges write the SAME fields Settings owns, so they announce themselves and say
        // where the setting lives. A silent write from a nudge is a second, hidden settings screen.
        : (a === 'cadence_daily' || a === 'cadence_single') ? () => {
            const daily = a === 'cadence_daily';
            update(d => { d.profile = d.profile || {}; d.profile.weighCadence = daily ? 'daily' : 'single'; });
            showToast && showToast((daily ? 'Weighing most mornings now.' : 'Weighing once a week now.') + ' Change it any time in Settings, Check-ins & weigh-ins.');
          }
        // The weekly weigh day, picked from the buddy's day row. Storing it is what lets the ask
        // arrive on the right morning instead of every morning.
        : a.indexOf('weighday_') === 0 ? () => { const dayIdx = +a.slice(9); update(d => { d.profile = d.profile || {}; d.profile.weighDay = dayIdx; }); showToast && showToast('Weigh-in day set to ' + DOW_FULL[dayIdx] + '. I’ll ask that morning, and you can change it in Settings, Check-ins & weigh-ins.'); }
        : a === 'log' ? () => onQuickAdd(false)
        : a === 'cook' ? () => { snoozeKey(btn.key); setView('recipes'); }
        : a === 'cook_fridge' ? () => { snoozeKey(btn.key); onOpenFridge(); }
        : a === 'progress' ? () => { snoozeKey(btn.key); setView('goals'); }
        : a === 'train' ? () => { snoozeKey(btn.key); setView('train'); }
        : (a === 'fight' || a === 'shop') ? () => { snoozeKey(btn.key); onOpenPlay(); }
        : a === 'instagram' ? () => { snoozeKey(btn.key); try { window.open('https://instagram.com/macrosaurus.app', '_blank'); } catch (_) {} }
        : a === 'feedback' ? () => { snoozeKey(btn.key); try { window.MFEEDBACK && window.MFEEDBACK(); } catch (_) {} }
        : a === 'recap_open' ? () => { ackRecap(); setRecapOpen(true); }
        : null;
      return { label: btn.label, onClick };
    };
    // Dismissing (×) a raised item. The weekly recap is acked for the week; everything else snoozes by
    // its key for its cooldown.
    const dismiss =
      m.kind === 'recap' ? ackRecap
      : (m.dismiss && m.dismiss.key) ? () => snoozeKey(m.dismiss.key)
      : null;
    // The inline weigh-in: seeded from the latest reading (or the profile weight for a first-timer)
    // and saved straight to today, so the buddy's ask and the logging are the same gesture.
    const weigh = m.weigh ? (() => {
      const ents = db.weight_entries || [];
      const latest = ents.reduce((a, w) => (!a || w.date > a.date ? w : a), null);
      return { unit: db.profile.weight_unit, seedKg: latest ? latest.scale_weight : db.profile.weightKg, onSave: saveTodayWeight };
    })() : null;
    return { kind: m.kind, text: m.text, meter: m.meter || null, weigh, choices: (m.choices || []).map(resolve), primary: resolve(m.primary), secondary: resolve(m.secondary), dismiss };
  })();
  return (
    <div className="max-w-md lg:max-w-2xl mx-auto px-5 pb-28 lg:pb-16 pt-6 fade-in">
      {hatching && <HatchCelebration buddy={db.buddy} suggestedName={randomBuddyName(db.game_salt)} onDone={(nm) => { setHatching(false); update(d => { d.buddy = d.buddy || { stage: 0 }; d.buddy.name = nm; d.buddy.hatched = true; d.buddy.stageSeen = Math.max(d.buddy.stageSeen || 0, d.buddy.stage || 0); d.onboarding = d.onboarding || {}; d.onboarding.hatched = true; }); if (showToast) showToast(nm + ' hatched! Keep logging to help it grow.'); }} />}
      {milestone && !hatching && <MilestoneCelebration db={db} milestone={milestone} etaText={milestoneEta} showToast={showToast} onClose={() => markMiles(milestone.coveredKeys)} onMaintain={milestone.kind === 'reached' ? () => { markMiles(milestone.coveredKeys); setView('goals'); } : null} />}
      {grewTo != null && !hatching && !milestone && <StageUpCelebration db={db} stage={grewTo} onClose={markGrown} />}
      {densityHelp && <DensityExplainer onClose={() => setDensityHelp(false)} />}
      <PageHeader kicker={prettyDate(today)} title="Today" />
      <WeekPlanBanner db={db} onOpen={() => setView('more')} />
      <OnboardingChecklist db={db} update={update} onLog={() => onQuickAdd(false)} onOpenDex={onOpenPlay} />
      {/* For free users, the upsell leads Today as the first box (dismissable, re-shows after 7 days so
          it never nags). Hidden during egg incubation so onboarding stays focused on hatching. */}
      {!isPremium && !eggIncubating && <PremiumNudge db={db} update={update} className="mb-4" reason="manual" trackKey="today_top"
        headline="Log a meal in one snap"
        blurb="Premium unlocks unlimited AI logging and scores the quality of everything you eat, so you can see how well you ate and not just how much. Try it free for 7 days." />}

      {/* The buddy leads Today. It used to sit below the macro card, which put it at y=871 on a
          390x844 phone against a fold of 844 - the app's whole relatedness layer was off screen
          on first paint. It earns its height rather than taking it: quiet when the ladder has
          nothing due, taller only when it is actually saying something. */}
      <BuddyHabitat db={db} buddy={buddy} bp={bp} streak={streak} onOpenPlay={onOpenPlay} tasks={eggIncubating ? hatchTasks : null} msg={msg} />

      {/* Hero: today's macros. One glance (what's left), the daily loop. One lens only (Left/Eaten);
          Balance is a power tool behind Adjust; everything secondary is in More below.
          The heading and the lens control used to float above the card on their own row. The card
          already announces itself ("KCAL LEFT"), so the heading restated it and the control sat
          detached from the numbers it changes. Both now live on the card's own top line. */}
      <Card className="p-5 mb-4" style={{ outline: '3px solid var(--accent)', outlineOffset: 2 }}>
        <MacroSummaryCard et={et} tot={tot} mode={mode} avg={false} entries={entriesOn(db, today)} onExplain={() => setDensityHelp(true)}
          lens={<Pill value={mode} onChange={setMode} options={[{ v: 'remaining', l: 'Left' }, { v: 'consumed', l: 'Eaten' }]} />} />
        {/* Balance (shift leftover kcal between carbs and fat) sits right under the bars it affects. */}
        <div className="mt-3 pt-2.5 border-t border-[#262629]">
          <Collapsible variant="inline" label="Balance carbs & fat" sub="Adjust ›">
            <div className="text-[12px] text-[#8A8A90] mb-3">Shift today's leftover calories between carbs and fat. Protein stays fixed.</div>
            <div className="flex justify-between text-[11px] text-[#8A8A90] mb-1"><span>More carbs</span><span>More fat</span></div>
            <input type="range" min="-400" max="400" step="10" value={override.shiftKcal} onChange={e => setShift(+e.target.value)} className="w-full accent-[#4A9EEB]" />
            <div className="flex justify-between items-center mt-3">
              <div className="leading-tight"><div className="text-[16px] font-bold tnum" style={{ color: CARB_T }}>{remCarbs}g</div><div className="pf text-[7px] uppercase text-[#8A8A90]">carbs left</div></div>
              {override.shiftKcal ? <button onClick={() => setShift(0)} className="pf text-[8px] uppercase" style={{ color: 'var(--accent-ink)' }}>Reset</button> : <span className="pf text-[8px] uppercase text-[#8A8A90]">Balanced</span>}
              <div className="text-right leading-tight"><div className="text-[16px] font-bold tnum" style={{ color: FAT_T }}>{remFat}g</div><div className="pf text-[7px] uppercase text-[#8A8A90]">fat left</div></div>
            </div>
          </Collapsible>
        </div>
        {/* Footers share one grid: muted label on the left, an accent tap-through on the right. */}
        {(et.cyc !== 0 || et.carry !== 0) && (() => {
          const adj = et.eff.kcal - et.base.kcal;
          const cd = et.carryDetail;
          const canOpen = !!(cd && cd.days && cd.days.length) || et.cyc !== 0;
          const label = (et.cyc && et.carry) ? 'adjusted' : et.cyc ? (et.cyc > 0 ? 'high day' : 'low day') : (et.carry > 0 ? 'carried over' : 'carried back');
          const sgn = n => (n > 0 ? '+' : n < 0 ? '−' : '') + Math.abs(n);
          return <div className="mt-3 pt-2.5 border-t border-[#262629] flex items-center justify-between text-[11px] text-[#8A8A90]">
            <span className="tnum"><span style={{ color: adj > 0 ? 'var(--good-ink)' : 'var(--fat-ink)' }}>{sgn(adj)}</span> kcal {label}</span>
            {canOpen && <button onClick={() => setShowCarry(true)} className="pf text-[8px] uppercase" style={{ color: 'var(--accent-ink)' }}>Details ›</button>}
          </div>;
        })()}
      </Card>

      {/* Compact companion: mood + a feed nudge, one tap into Play. The full buddy detail (hearts,
          needs, evolution) now lives in the Play hub so Today stays a calm glance. */}
      {readyOpen && <BuddyReadinessSheet db={db} onClose={() => setReadyOpen(false)} onWeigh={() => onWeigh(true)} />}
      {recapOpen && <WeeklyRecapSheet db={db} onClose={() => setRecapOpen(false)} onOpenProgress={() => { setRecapOpen(false); setView('goals'); }} />}

      {/* Move / Sleep / Ready glance (Google Health), prominent on Today. Shows the dials when there's
          data, or a prominent Connect invite when not linked. The Fight payoff lives in Play. */}
      <StepsSleepCard db={db} update={update} onOpenPlay={onOpenPlay} onCheckIn={onCheckIn} />

      {/* Only ever renders when a diet break is active or genuinely due, so it stays out of the way. */}
      <DietBreakCard db={db} update={update} />

      {/* The "More" drawer is gone (install lives in Account, the upsell is the top box). Only the
          contextual "AI logs left" nudge remains, and only when it's genuinely running low. */}
      {!isPremium && (() => {
        const freeLeft = Math.max(0, FREE_AI_MONTHLY - (aiCalls || 0));
        return freeLeft <= 3
          ? <PremiumNudge db={db} update={update} className="mb-4" reason="free_limit" trackKey="dash_ai_low"
              headline={freeLeft > 0 ? (freeLeft + ' AI log' + (freeLeft === 1 ? '' : 's') + ' left this month') : "You've used your free AI logs"}
              blurb="Premium is unlimited photo, label and describe logging, so you never run out mid-month. 7 days free, then cancel anytime." />
          : null;
      })()}

      <div className="text-center text-[10px] text-[#8A8A90] mt-8 px-4 leading-relaxed">{quote}</div>
      {showCarry && <CarryoverSheet et={et} onClose={() => setShowCarry(false)} />}
    </div>
  );
}

function CarryoverSheet({ et, onClose }) {
  useBackClose(onClose);
  const cd = et.carryDetail;
  const sgn = n => (n > 0 ? '+' : n < 0 ? '−' : '') + Math.abs(n);
  const dd = d => new Date(d + 'T00:00:00').toLocaleDateString('en-GB', { weekday: 'short', day: 'numeric', month: 'short' });
  const dShort = d => new Date(d + 'T00:00:00').toLocaleDateString('en-GB', { weekday: 'short' });
  const maxAbs = (cd && cd.days.length) ? Math.max(1, ...cd.days.map(d => Math.abs(d.delta))) : 1;
  const Row = ({ label, val, color, bold }) => (
    <div className="flex justify-between tnum text-[11px] py-1">
      <span className={bold ? 'font-bold' : 'text-[#8A8A90]'} style={bold ? { color: 'var(--text)' } : null}>{label}</span>
      <span className="font-bold" style={color ? { color } : (bold ? { color: 'var(--text)' } : null)}>{val}</span>
    </div>
  );
  return (
    <div className="fixed inset-0 z-[80] bg-black/70 flex items-end sm:items-center justify-center" onClick={onClose}>
      <div className="bg-[#0F0F12] w-full max-w-md pixel-box p-5 max-h-[90vh] overflow-y-auto sheet-up" style={{ paddingBottom: 'calc(1.75rem + env(safe-area-inset-bottom))' }} onClick={e => e.stopPropagation()}>
        <div className="flex justify-between items-center mb-1"><h2 className="text-lg font-semibold">Today's target</h2><button onClick={onClose} className="w-11 h-11 flex items-center justify-center shrink-0 text-[#8A8A90] text-2xl leading-none">×</button></div>
        <div className="text-[11px] text-[#8A8A90] mb-4 leading-snug">Where today's {et.eff.kcal} kcal comes from.</div>

        <div className="pixel-box p-3 mb-4" style={{ background: 'var(--surface3)', boxShadow: 'none' }}>
          <Row label="Base target" val={et.base.kcal} />
          {et.cyc !== 0 && <Row label={et.cyc > 0 ? 'High day' : 'Low day'} val={sgn(et.cyc)} color={et.cyc > 0 ? 'var(--good)' : 'var(--fat)'} />}
          {et.carry !== 0 && <Row label={et.carry > 0 ? 'Carried over' : 'Carried back'} val={sgn(et.carry)} color={et.carry > 0 ? 'var(--good)' : 'var(--fat)'} />}
          <div className="border-t border-[#262629] mt-1 pt-1"><Row label="Today you get" val={et.eff.kcal + ' kcal'} bold /></div>
        </div>

        {cd && cd.days.length > 0 && <>
          <div className="pf text-[8px] uppercase text-[#8A8A90] mb-3">This week · since {dd(cd.cycleStart)}</div>
          <div className="flex items-end gap-1.5 mb-2" style={{ height: '64px' }}>
            {cd.days.map((d, i) => {
              const h = Math.round(5 + (Math.abs(d.delta) / maxAbs) * 40);
              const under = d.delta > 0, over = d.delta < 0;
              return <div key={i} className="flex-1 flex flex-col items-center justify-end" style={{ height: '100%' }}>
                <span className="tnum text-[7px] mb-1" style={{ color: under ? 'var(--good-ink)' : over ? 'var(--fat-ink)' : 'var(--muted)' }}>{sgn(d.delta)}</span>
                <div style={{ width: '100%', height: h + 'px', background: under ? 'var(--good)' : over ? 'var(--fat)' : 'var(--border)' }}></div>
              </div>;
            })}
          </div>
          <div className="flex gap-1.5 mb-3">
            {cd.days.map((d, i) => <div key={i} className="flex-1 text-center pf text-[7px] text-[#8A8A90]">{dShort(d.date)}</div>)}
          </div>
          <div className="flex justify-between text-[9px] text-[#8A8A90] mb-4">
            <span><span style={{ color: 'var(--good-ink)' }}>■</span> under target</span>
            <span><span style={{ color: 'var(--fat-ink)' }}>■</span> over target</span>
          </div>

          <div className="pixel-box p-3 mb-3 flex justify-between items-center tnum text-[11px]" style={{ background: 'var(--surface3)', boxShadow: 'none' }}>
            <span className="font-bold">Running balance</span>
            <span className="font-bold" style={{ color: cd.balance > 0 ? 'var(--good-ink)' : cd.balance < 0 ? 'var(--fat-ink)' : 'var(--text)' }}>{sgn(cd.balance)} kcal</span>
          </div>

          <div className="text-[10px] text-[#8A8A90] leading-relaxed">{cd.mode === 'dispersed'
            ? `Evened out across the week: this ${sgn(cd.balance)} balance spreads over the ${cd.remaining} day${cd.remaining === 1 ? '' : 's'} left, so ${sgn(cd.applied)} lands on today.`
            : `Onto the next day: the whole ${sgn(cd.balance)} balance lands on today (${sgn(cd.applied)}), capped at ±${cd.cap} kcal a day.`}</div>
        </>}

        <button onClick={onClose} className="pixel-btn w-full mt-4 py-2.5 text-[11px]" style={{ background: 'var(--surface2)' }}>Got it</button>
      </div>
    </div>
  );
}

/* =====================================================================
   FOOD LOG (calendar + diary)
   ===================================================================== */
const PAW_GRID = ['#..#..#', '#..#..#', '.#.#.#.', '.#.#.#.', '..###..', '.#####.', '.#####.', '..###..'];
function PixelGrip() {
  // A universal drag handle: two columns of pixel dots (clearer than the old paw glyph).
  const pts = [[1, 1], [4, 1], [1, 3], [4, 3], [1, 5], [4, 5]];
  return <svg viewBox="0 0 6 7" width="14" height="16" fill="currentColor" style={{ imageRendering: 'pixelated', shapeRendering: 'crispEdges', display: 'block' }}>{pts.map(([x, y], i) => <rect key={i} x={x} y={y} width="1" height="1" />)}</svg>;
}
function FoodLog({ db, update, openLog, showToast }) {
  const today = Store.todayISO();
  const [date, setDate] = useState(today);
  const [menu, setMenu] = useState(null);
  const [mealMenu, setMealMenu] = useState(null);
  const [editing, setEditing] = useState(null);
  const [dayMenu, setDayMenu] = useState(false);
  const swipe = useRef(null); // swipe-between-days: touchstart point, consumed on touchend
  const [editMeal, setEditMeal] = useState(null); const [mealName, setMealName] = useState('');
  const [nameSheet, setNameSheet] = useState(null); // { meal, entries } for "Save as meal"
  const [densityHelp, setDensityHelp] = useState(false); // the Density Score explainer, opened from the day card
  const [showCal, setShowCal] = useState(false);
  const [copyTo, setCopyTo] = useState(null);
  const [photoUp, setPhotoUp] = useState(null); // the entry being re-estimated from a photo taken later
  const [confirm, setConfirm] = useState(null);
  const [calMonth, setCalMonth] = useState(() => { const d = new Date(today + 'T00:00:00'); return { y: d.getFullYear(), m: d.getMonth() }; });
  const meals = mealsForDay(db, date);
  // Forward-looking days (paging/swiping into the future) use the projected target so carryover
  // is shown paid-down day by day, not the whole running balance dumped onto every future day.
  // Today and past days resolve to their real effectiveTarget inside the helper.
  const day = entriesOn(db, date); const et = weekForecastTargets(db, [date])[date]; const tot = sumMacros(day);
  const override = (db.day_overrides || {})[date] || { shiftKcal: 0 };
  const setShift = (v) => update(d => { d.day_overrides = Object.assign({}, d.day_overrides || {}, { [date]: { shiftKcal: v } }); });
  const remCarbs = et ? Math.max(0, Math.round(et.eff.carbs_g - tot.carbs)) : 0;
  const remFat = et ? Math.max(0, Math.round(et.eff.fat_g - tot.fat)) : 0;
  const toast = (m, a, fn) => showToast && showToast(m, a, fn);
  const del = (e) => { update(d => { tombstone(d, [e.id]); d.log_entries = d.log_entries.filter(x => x.id !== e.id); }); setMenu(null); toast('Deleted ' + e.name, 'Undo', () => update(d => { untombstone(d, [e.id]); d.log_entries.push(e); })); };
  const dup = (e) => { update(d => d.log_entries.push(Object.assign({}, e, { id: Store.uid() }))); setMenu(null); };
  const copyEntriesTo = (entries, targetDate, targetMeal) => {
    const copies = entries.map(e => Object.assign({}, e, { id: Store.uid(), date: targetDate }, targetMeal ? { meal_id: targetMeal } : {}));
    update(d => copies.forEach(c => d.log_entries.push(c))); setCopyTo(null);
    const lbl = targetDate === today ? 'today' : targetDate === shiftISO(today, 1) ? 'tomorrow' : new Date(targetDate + 'T00:00:00').toLocaleDateString('en-GB', { day: 'numeric', month: 'short' });
    toast(copies.length + (copies.length === 1 ? ' item' : ' items') + ' copied to ' + lbl, 'Undo', () => update(d => { const idl = copies.map(c => c.id); tombstone(d, idl); const ids = new Set(idl); d.log_entries = d.log_entries.filter(x => !ids.has(x.id)); }));
  };
  const clearMeal = (m, me) => { const removed = me.slice(); update(d => { tombstone(d, removed.map(x => x.id)); d.log_entries = d.log_entries.filter(x => !(x.meal_id === m.id && x.date === date)); }); setMealMenu(null); toast('Cleared ' + m.name, 'Undo', () => update(d => { untombstone(d, removed.map(x => x.id)); removed.forEach(e => d.log_entries.push(e)); })); };
  // ---- per-day meal editing (only this date; other days + the Settings default are untouched) ----
  const renameMeal = (m, name) => { if (!name.trim()) return; update(d => { const arr = ensureDayMeals(d, date); const mm = arr.find(x => x.id === m.id); if (mm) mm.name = name.trim(); }); };
  const addDayMeal = () => update(d => { const arr = ensureDayMeals(d, date); const maxS = arr.length ? Math.max.apply(null, arr.map(x => x.sort_order)) : -1; arr.push({ id: Store.uid(), user_id: Store.USER, name: 'Meal ' + (arr.length + 1), sort_order: maxS + 1 }); });
  const moveMeal = (m, dir) => update(d => { const arr = ensureDayMeals(d, date); arr.sort((a, b) => a.sort_order - b.sort_order); const i = arr.findIndex(x => x.id === m.id); const j = dir < 0 ? i - 1 : i + 1; if (j < 0 || j >= arr.length) return; const t = arr[i]; arr[i] = arr[j]; arr[j] = t; arr.forEach((x, k) => x.sort_order = k); });
  const deleteMeal = (m) => {
    const hadOverride = !!(db.day_meals && db.day_meals[date]);
    const prevMeals = hadOverride ? db.day_meals[date].map(x => Object.assign({}, x)) : null;
    const affected = day.filter(e => e.meal_id === m.id).map(e => e.id);
    update(d => {
      const arr = ensureDayMeals(d, date); arr.sort((a, b) => a.sort_order - b.sort_order);
      const i = arr.findIndex(x => x.id === m.id); if (i < 0) return;
      const target = arr[i - 1] || arr[i + 1] || null;
      if (target && affected.length) { const ids = new Set(affected); d.log_entries.forEach(e => { if (ids.has(e.id)) e.meal_id = target.id; }); }
      arr.splice(i, 1); arr.forEach((x, k) => x.sort_order = k);
    });
    setMealMenu(null);
    toast('Deleted ' + m.name, 'Undo', () => update(d => {
      if (!d.day_meals) d.day_meals = {};
      if (prevMeals) d.day_meals[date] = prevMeals; else delete d.day_meals[date];
      const ids = new Set(affected); d.log_entries.forEach(e => { if (ids.has(e.id)) e.meal_id = m.id; });
    }));
  };
  // Opens the in-app naming sheet (no more window.prompt); the save itself happens in its onSave.
  const saveMeal = (m, me) => { setMealMenu(null); setNameSheet({ meal: m, entries: me.slice() }); };
  const saveEdit = (patch) => { applyEntryPatch(update, editing.id, patch); setEditing(null); toast('Updated ' + patch.name); };
  /* A photo update is destructive in a way an ordinary edit is not: it throws away numbers the user
     may have hand-corrected, and it is the AI that decided to. So the Undo carries the WHOLE entry
     as it was, restored by id, rather than trying to reverse a patch. The toast leads with both
     figures, because "820 kcal" on its own does not tell you whether the photo changed anything. */
  const savePhotoUpdate = (entry, item) => {
    const prev = JSON.parse(JSON.stringify(entry));
    const was = Math.round((entry.computed_macros || {}).kcal || 0);
    const now = Math.round((item.macros || {}).kcal || 0);
    applyPhotoEstimate(update, entry.id, item);
    setPhotoUp(null);
    try { window.MTRACK && MTRACK('photo_update', { outcome: 'saved', was: was, now: now }); } catch (_) {}
    toast((item.name || entry.name) + ': ' + was + ' → ' + now + ' kcal', 'Undo', () => update(d => {
      const i = d.log_entries.findIndex(x => x.id === prev.id);
      if (i >= 0) d.log_entries[i] = prev;
    }));
  };

  // ---- drag & drop: move a logged entry to another meal / reorder within a meal ----
  const [drag, setDrag] = useState(null);   // { id, name, mc }
  const [ghost, setGhost] = useState(null); // { x, y } floating chip position
  const [dropAt, setDropAt] = useState(null); // { mealId, beforeId }
  const moveEntry = (dragId, targetMealId, beforeId) => update(d => {
    const arr = d.log_entries; const idx = arr.findIndex(x => x.id === dragId); if (idx < 0) return;
    const item = arr.splice(idx, 1)[0]; item.meal_id = targetMealId;
    let insertAt;
    if (beforeId) { insertAt = arr.findIndex(x => x.id === beforeId); if (insertAt < 0) insertAt = arr.length; }
    else { let last = -1; for (let i = 0; i < arr.length; i++) { if (arr[i].date === date && arr[i].meal_id === targetMealId) last = i; } insertAt = last >= 0 ? last + 1 : arr.length; }
    arr.splice(insertAt, 0, item);
  });
  const beginDrag = (entry, mc, x, y) => { const m = entry.computed_macros || {}; setDrag({ id: entry.id, name: entry.name, mc, kind: foodKind(entry.name, entry.is_alcohol), kcal: Math.round(m.kcal || 0), qty: entry.qty_label, p: m.protein, c: m.carbs, f: m.fat }); setGhost({ x, y }); if (navigator.vibrate) { try { navigator.vibrate(10); } catch (e) {} } };
  // Press and hold anywhere on the row to pick it up; a plain tap opens it for editing. The grab
  // handle this replaced was a permanent 38px column on a row that only had 295px to begin with,
  // and the row's one job is to be readable. 450ms is the conventional long-press: the old 180ms
  // was tuned for a dedicated handle, where nothing else could have been meant, and would now
  // arm a drag on a great many ordinary taps.
  const [arming, setArming] = useState(null); // entry id currently being held
  // When a drag ends the browser may or may not fire a click, depending on whether the pointer
  // moved and on the platform, so a plain "swallow the next click" flag can be left set forever and
  // eat a real tap on some other row later. A timestamp cannot get stuck: clicks are ignored only
  // in the moment right after a drag, and it heals itself whatever the browser decides to send.
  const draggedAt = useRef(0);
  const startDrag = (ev, entry, mc) => {
    if (ev.button != null && ev.button !== 0) return;
    // No preventDefault here: it would cancel the click this row now depends on. Selection and the
    // long-press callout are held off in CSS on the row instead.
    ev.stopPropagation(); setMenu(null); setMealMenu(null);
    const sx = ev.clientX, sy = ev.clientY; setArming(entry.id);
    const timer = setTimeout(() => { cleanup(); setArming(null); draggedAt.current = Date.now(); beginDrag(entry, mc, sx, sy); }, 450);
    const onMove = (e) => { if (Math.hypot(e.clientX - sx, e.clientY - sy) > 10) { clearTimeout(timer); cleanup(); setArming(null); } };
    const onUp = () => { clearTimeout(timer); cleanup(); setArming(null); };
    function cleanup() { window.removeEventListener('pointermove', onMove); window.removeEventListener('pointerup', onUp); window.removeEventListener('pointercancel', onUp); }
    window.addEventListener('pointermove', onMove, { passive: true });
    window.addEventListener('pointerup', onUp); window.addEventListener('pointercancel', onUp);
  };
  useEffect(() => {
    if (!drag) return;
    const computeDrop = (x, y) => {
      // Walk every element under the finger, skipping the floating drag preview, and take
      // the first logged row (preferred) or meal drop-zone we hit.
      const els = (document.elementsFromPoint ? document.elementsFromPoint(x, y) : [document.elementFromPoint(x, y)]).filter(Boolean);
      let mealEl = null;
      for (let i = 0; i < els.length; i++) {
        const el = els[i]; if (!el.closest || el.closest('[data-ghost]')) continue;
        const row = el.closest('[data-entry-id]');
        if (row) {
          const mealId = row.getAttribute('data-meal-id'); const eid = row.getAttribute('data-entry-id');
          const r = row.getBoundingClientRect(); const after = y > r.top + r.height / 2;
          const list = entriesOn(db, date).filter(e => e.meal_id === mealId).map(e => e.id);
          const idx = list.indexOf(eid); const beforeId = after ? (list[idx + 1] || null) : eid;
          return { mealId, beforeId };
        }
        if (!mealEl) { const me = el.closest('[data-meal-drop]'); if (me) mealEl = me; }
      }
      if (mealEl) return { mealId: mealEl.getAttribute('data-meal-drop'), beforeId: null };
      return null;
    };
    const move = (ev) => {
      const x = ev.clientX, y = ev.clientY; setGhost({ x, y }); setDropAt(computeDrop(x, y));
      const es = y < 100 ? -14 : y > window.innerHeight - 130 ? 14 : 0; if (es) window.scrollBy(0, es);
      ev.preventDefault();
    };
    const up = (ev) => {
      // Re-stamp on the drop, not just when the drag armed: a long drag can easily outlast the
      // window measured from the press, and it is the click after the DROP that has to be ignored.
      draggedAt.current = Date.now();
      const t = computeDrop(ev.clientX, ev.clientY);
      if (t && t.beforeId !== drag.id) moveEntry(drag.id, t.mealId, t.beforeId);
      setDrag(null); setDropAt(null); setGhost(null);
    };
    window.addEventListener('pointermove', move, { passive: false });
    window.addEventListener('pointerup', up); window.addEventListener('pointercancel', up);
    const prevSel = document.body.style.userSelect; document.body.style.userSelect = 'none';
    return () => { window.removeEventListener('pointermove', move); window.removeEventListener('pointerup', up); window.removeEventListener('pointercancel', up); document.body.style.userSelect = prevSel; };
  }, [drag]);

  const renderEntry = (e, m, mc) => { const dragging = drag && drag.id === e.id; return (
    <div key={e.id} data-entry-id={e.id} data-meal-id={m.id} className="flex items-center gap-2 py-2.5 mt-2 relative" style={{ borderTop: '1px solid var(--surface2)', borderLeft: '4px solid ' + mc, paddingLeft: 8, opacity: dragging ? 0.45 : 1, outline: dragging ? '2px dashed var(--muted)' : 'none', outlineOffset: '-2px', background: dragging ? 'var(--surface2)' : undefined }}>
      {drag && dropAt && dropAt.mealId === m.id && dropAt.beforeId === e.id && <div className="absolute -top-1 left-0 right-0 h-1.5 pointer-events-none" style={{ background: 'var(--accent)', boxShadow: '2px 2px 0 0 var(--shadow)' }} />}
      {/* The food tile: a pixel glyph of what this is, in the colour of how good it is.
          It came back, smaller and re-pointed, after being cut entirely. Cutting it was half right:
          at 36px in an arbitrary per-meal hue it stole the name's width and coloured nothing
          meaningful. But a list of names in one weight is slow AND joyless, and the research is
          blunt about the cost: people find an item about 37% faster when rows differ by colour AND
          icon rather than text alone. So the tile is back at 28px, and its colour is the Density
          Score, which makes the fun and the information the same pixel: a green tile is a good
          choice, an amber one is middling, and you read that before you read a word.
          A food we could not score keeps its glyph on a plain outlined tile, so an unscored row
          still has a face rather than being a hole in the list. */}
      {/* The row itself is the control: tap to edit, press and hold to move it. Editing used to be
          two taps behind the ⋯ menu, which is not where anyone looks for it, and is not what the
          rest of the category does. */}
      <button
        onClick={() => { if (Date.now() - draggedAt.current < 500) return; setMenu(null); setMealMenu(null); setEditing(e); }}
        onPointerDown={(ev) => startDrag(ev, e, mc)}
        className="flex items-center gap-2 min-w-0 flex-1 text-left"
        style={{ userSelect: 'none', WebkitUserSelect: 'none', WebkitTouchCallout: 'none', transform: arming === e.id ? 'scale(.985)' : 'none', transition: 'transform .16s ease' }}
        title="Tap to edit, press and hold to move">
      <FoodTile name={e.name} isAlcohol={e.is_alcohol} nq={e.nq} />
      {/* The food's NAME is the thing you scan for, so it gets the row's width and the only real
          type weight. Everything else is support, on one quiet line beneath in text ink. */}
      <div className="min-w-0 flex-1">
        {/* The name wraps to a second line rather than clipping. A row is scanned by its name, and
            "Porridge, ban…" fails at the one job the row has; an occasional two-line row is a much
            smaller cost than a name you cannot read. Capped at two lines so nothing runs away. */}
        {/* The name owns its line outright. Sharing it with the calories left only 136px, about
            sixteen characters, so anything longer than "Chicken & rice bowl" wrapped and then
            clipped anyway. The calories move down to lead the support line, where they are still
            the first thing on it and still the boldest thing on it. */}
        {/* The amount rides with the name. Measured, the support line needs 286px to hold calories,
            amount, macros and the score, and it has 216: something had to move or be cut. Up here
            it costs nothing, because this box WRAPS to a second line rather than truncating, so
            "· 360 g" simply flows on after the name instead of clipping anything. */}
        <div className="min-w-0">
          <span className="text-[13.5px]" style={{ display: '-webkit-box', WebkitLineClamp: 2, WebkitBoxOrient: 'vertical', overflow: 'hidden', lineHeight: 1.25 }}>{e.name}
            {e.qty_label ? <span style={{ color: 'var(--muted)' }}>{' · ' + e.qty_label}</span> : ''}</span>
        </div>
        {/* The macros are back, now that dropping the grab handle and moving the amount up have paid
            for them. They earn the place: this is a macro tracker, and "how much protein was that?"
            is the question the row is actually asked. They were cut before because they shared one
            truncating span with the amount and were what got clipped mid-digit; with the amount gone
            from this line the whole thing fits, and nothing here truncates at all. */}
        {/* No "·" between the calories and the macros: it measured 16px, which was exactly the
            16px the line was over by, and the colour change already does a separator's job. */}
        <div className="flex items-center gap-1.5 mt-1 min-w-0">
          <span className="text-[11px] tnum truncate min-w-0">
            <span className="font-bold" style={{ color: 'var(--text2)' }}>{Math.round(e.computed_macros.kcal)} kcal</span>{'  '}
            <span style={{ color: PRO_T }}>P{Math.round(e.computed_macros.protein || 0)}</span>{' '}
            <span style={{ color: CARB_T }}>C{Math.round(e.computed_macros.carbs || 0)}</span>{' '}
            <span style={{ color: FAT_T }}>F{Math.round(e.computed_macros.fat || 0)}</span>
          </span>
          {/* Just the score. The blocks moved into the tile's colour, so repeating them here would
              say the same thing twice in one row. The number stays because colour alone is not a
              channel everyone has, and a phone has no hover to fall back on. */}
          <DensityScoreText nq={e.nq} className="shrink-0" />
        </div>
      </div>
      </button>
      <button onClick={(ev) => { ev.stopPropagation(); setMealMenu(null); setMenu(menu === e.id ? null : e.id); }} className="hit px-2 text-[#8A8A90] shrink-0" aria-label="Entry options">⋯</button>
      {menu === e.id && (<div className="absolute right-2 top-9 z-20 bg-[#1E1E22] border border-[#262629] rounded-2xl py-1 text-sm shadow-xl" onClick={ev => ev.stopPropagation()}>
        <button onClick={() => { setEditing(e); setMenu(null); }} className="block w-full text-left px-4 py-2 hover:bg-[#262629]">Edit</button>
        {E.photoUpdatable(e) && <button onClick={() => { setPhotoUp(e); setMenu(null); }} className="block w-full text-left px-4 py-2 hover:bg-[#262629]">Update with a photo</button>}
        <button onClick={() => dup(e)} className="block w-full text-left px-4 py-2 hover:bg-[#262629]">Duplicate</button>
        <button onClick={() => { setCopyTo({ title: 'Copy ' + e.name, entries: [e], srcDate: date, pickMeal: true, meal: e.meal_id }); setMenu(null); }} className="block w-full text-left px-4 py-2 hover:bg-[#262629]">Copy to…</button>
        <button onClick={() => del(e)} className="block w-full text-left px-4 py-2 text-[#ff6b6b] hover:bg-[#262629]">Delete</button>
      </div>)}
    </div>); };

  const first = new Date(calMonth.y, calMonth.m, 1); const startDow = (first.getDay() + 6) % 7; // Mon=0
  const daysIn = new Date(calMonth.y, calMonth.m + 1, 0).getDate();
  const cells = []; for (let i = 0; i < startDow; i++) cells.push(null);
  for (let dd = 1; dd <= daysIn; dd++) cells.push(Store.isoOf(new Date(calMonth.y, calMonth.m, dd)));
  const logSet = new Set(db.log_entries.map(e => e.date));
  const monthName = new Date(calMonth.y, calMonth.m, 1).toLocaleDateString('en-GB', { month: 'long', year: 'numeric' });

  return (
    <div className="max-w-md lg:max-w-5xl mx-auto px-5 pb-28 lg:pb-12 pt-6 fade-in"
      onClick={() => { if (menu) setMenu(null); if (mealMenu) setMealMenu(null); if (dayMenu) setDayMenu(false); }}
      onTouchStart={(e) => { if (drag || showCal) return; const t = e.touches[0]; swipe.current = { x: t.clientX, y: t.clientY }; }}
      onTouchEnd={(e) => { if (!swipe.current || drag) { swipe.current = null; return; } const t = e.changedTouches[0]; const dx = t.clientX - swipe.current.x, dy = t.clientY - swipe.current.y; swipe.current = null; if (Math.abs(dx) > 60 && Math.abs(dx) > Math.abs(dy) * 1.6) { setDate(shiftISO(date, dx < 0 ? 1 : -1)); setShowCal(false); } }}>
      {densityHelp && <DensityExplainer onClose={() => setDensityHelp(false)} />}
      <PageHeader kicker="Your food diary" title="Food log" />
      <div className="lg:grid lg:grid-cols-2 lg:gap-6 lg:items-start">
      <div className="min-w-0">
      {/* Swipe left/right to change day, or tap the arrows. Tap the date for the month calendar; day-level
          actions (add a meal, copy the day) live behind the one day menu so nothing stacks below. */}
      <div className="flex items-center gap-1 mb-4">
        <button onClick={() => setDate(shiftISO(date, -1))} className="text-[#8A8A90] px-3 py-2 text-lg" aria-label="Previous day">‹</button>
        <button onClick={() => { if (!showCal) { const d = new Date(date + 'T00:00:00'); setCalMonth({ y: d.getFullYear(), m: d.getMonth() }); } setShowCal(s => !s); }} className="flex-1 flex items-center justify-center gap-2 px-3 py-2 rounded-full bg-[#1E1E22] border border-[#262629]">
          <span className="text-sm font-semibold">{date === today ? 'Today' : date === shiftISO(today, 1) ? 'Tomorrow' : new Date(date + 'T00:00:00').toLocaleDateString('en-GB', { weekday: 'short', day: 'numeric', month: 'short' })}</span>
          <span className="text-[#8A8A90] text-[10px]">{showCal ? '▲' : '▼'}</span>
        </button>
        <button onClick={() => setDate(shiftISO(date, 1))} className="text-[#8A8A90] px-3 py-2 text-lg" aria-label="Next day">›</button>
        <div className="relative">
          <button onClick={ev => { ev.stopPropagation(); setMenu(null); setMealMenu(null); setDayMenu(v => !v); }} className="hit px-2 py-2 text-[#8A8A90]" aria-label="Day options">⋯</button>
          {dayMenu && <div className="absolute right-0 top-10 z-20 bg-[#1E1E22] border border-[#262629] rounded-2xl py-1 text-sm shadow-xl w-44" onClick={ev => ev.stopPropagation()}>
            <button onClick={() => { addDayMeal(); setDayMenu(false); }} className="block w-full text-left px-4 py-2 hover:bg-[#262629]">Add a meal</button>
            {day.length > 0 && <button onClick={() => { setCopyTo({ title: 'Copy this whole day', entries: day, srcDate: date }); setDayMenu(false); }} className="block w-full text-left px-4 py-2 hover:bg-[#262629]">Copy this day to…</button>}
            {/* The reciprocal pointer. Settings explains that per-day edits don't touch the default;
                until now the Food log never said the default existed. */}
            <div className="text-[11px] text-[#8A8A90] px-4 py-2 leading-snug" style={{ borderTop: '1px solid #262629' }}>Meal changes here apply to this day only. Settings, Default meals sets the layout for every new day.</div>
          </div>}
        </div>
      </div>
      {showCal && <Card className="p-4 mb-4 fade-in">
        <div className="flex items-center justify-between mb-2">
          <button onClick={() => setCalMonth(c => { const m = c.m - 1; return m < 0 ? { y: c.y - 1, m: 11 } : { y: c.y, m }; })} className="text-[#8A8A90] px-2 py-1">‹</button>
          <div className="text-sm font-semibold">{monthName}</div>
          <button onClick={() => setCalMonth(c => { const m = c.m + 1; return m > 11 ? { y: c.y + 1, m: 0 } : { y: c.y, m }; })} className="text-[#8A8A90] px-2 py-1">›</button>
        </div>
        <div className="grid grid-cols-7 gap-1 text-center text-[10px] text-[#8A8A90] mb-1">{['M', 'T', 'W', 'T', 'F', 'S', 'S'].map((d, i) => <div key={i}>{d}</div>)}</div>
        <div className="grid grid-cols-7 gap-1">{cells.map((c, i) => c ? (
          <button key={i} onClick={() => { setDate(c); setShowCal(false); }} className={`aspect-square rounded-lg text-[12px] tnum flex flex-col items-center justify-center relative ${c === date ? 'bg-white text-black font-bold' : c === today ? 'bg-[#1E1E22] text-white' : c > today ? 'text-[#8A8A90]' : 'text-[#C9C9CF]'}`}>
            {new Date(c + 'T00:00:00').getDate()}
          </button>) : <div key={i} />)}</div>
      </Card>}

      {/* Slim remaining-at-a-glance while you log; the full hero + Balance live on the Today tab. */}
      {et && (() => {
        const rem = et.eff.kcal - tot.kcal;
        const over = rem < 0;
        return <Card className="p-4 mb-4">
          <div className="flex items-baseline justify-between mb-3">
            <div className="flex items-baseline gap-1.5">
              <span className="pf text-[8px] uppercase text-[#8A8A90]">{over ? 'Over by' : 'Kcal left'}</span>
              <span className="text-2xl font-bold tnum" style={{ color: over ? 'var(--danger-ink)' : 'var(--hero)' }}>{Math.abs(Math.round(rem))}</span>
            </div>
            <span className="text-[10px] text-[#8A8A90] tnum">of {et.eff.kcal}</span>
          </div>
          {/* The same blocks as Today, laid out on one line each because this card is a reminder of
              where the day stands rather than the place you study it. Same instrument, same reading. */}
          <div className="space-y-2">
            {[['PROT', tot.protein, et.eff.protein_g, PRO], ['CARB', tot.carbs, et.eff.carbs_g, CARB], ['FATS', tot.fat, et.eff.fat_g, FAT]].map(([l, e, t, c]) => (
              <div key={l} className="flex items-center gap-2.5">
                <span className="pf text-[8px] w-8 shrink-0" style={{ color: 'var(--muted)' }}>{l}</span>
                <div className="flex-1 min-w-0"><PipMeter value={e} target={t} color={c} small /></div>
                <span className="tnum text-[10px] w-[64px] text-right shrink-0 whitespace-nowrap" style={{ color: e > t ? 'var(--danger-ink)' : 'var(--text2)' }}>
                  {e > t ? Math.round(e - t) + 'g over' : Math.max(0, Math.round(t - e)) + 'g left'}
                </span>
              </div>
            ))}
            {/* Density belongs here: this is the page where you are looking at the food that produced
                the score. It takes the same one-line shape as the macros above rather than the taller
                Today treatment, because this card is a reminder of where the day stands, not the place
                you study it. Scored for THIS date, so paging back a day scores that day.
                Premium only, and unlike Today it carries no locked upsell row: the upgrade path is
                already on Today, and a second one on the next tab along is nagging rather than
                offering. */}
            {(() => {
              if (window.MISPREMIUM !== true) return null;
              const dnd = E.ndDay(day.map(e => ({ kcal: (e.computed_macros || {}).kcal, nq: e.nq, alcohol: !!e.is_alcohol })));
              return (
                <button onClick={() => setDensityHelp(true)} className="w-full flex items-center gap-2.5 active:opacity-70" style={{ minHeight: 24 }}>
                  <span className="pf text-[8px] w-8 shrink-0 text-left" style={{ color: 'var(--muted)' }}>DENS</span>
                  <div className="flex-1 min-w-0">
                    <PipMeter value={dnd.score == null ? 0 : dnd.score} target={dnd.target} cells={10}
                      scale={100 / dnd.target} color={densityColor(dnd.score)} small overIsFine />
                  </div>
                  <span className="tnum text-[10px] w-[64px] text-right shrink-0 whitespace-nowrap"
                    style={{ color: dnd.score == null ? 'var(--muted)' : (dnd.hit ? 'var(--good-ink)' : 'var(--text2)') }}>
                    {dnd.score == null ? 'no score' : dnd.score + ' / ' + dnd.target}
                  </span>
                </button>
              );
            })()}
          </div>
        </Card>;
      })()}

      </div>

      <div className="min-w-0">
      {db.log_entries.length === 0 && <Card className="p-4 mb-3 fade-in" style={{ borderTopColor: 'var(--accent)', borderTopWidth: '5px' }}>
        <div className="text-[13px] font-semibold mb-1">Log your first item</div>
        <div className="text-[11px] text-[#8A8A90] leading-relaxed">Tap <span className="text-[#4A9EEB] font-medium">+ Add food</span> on any meal below, or the big ✚ button. You can snap a label photo, describe a meal out loud, scan a barcode, or search, the AI does the maths and you just confirm.</div>
      </Card>}
      {meals.map((m, mi) => {
        const me = day.filter(e => e.meal_id === m.id); const ms = sumMacros(me);
        // Meals used to cycle through five hues by position, three of which were the protein, carb
        // and fat identity colours. So a Breakfast stripe was the same red as the protein meter
        // directly above it, implying a link that does not exist, and a meal's colour changed if you
        // reordered your day. Meals are groups, not values: the card and its name already say which
        // meal you are looking at, so the stripe just separates rows and stays out of the way.
        const mc = 'var(--border)';
        // An empty meal gets a tighter card. Four full-size boxes for four meals is most of a screen
        // spent on the meals you have NOT eaten yet, so a day that is going fine reads as mostly
        // empty. It stays a card rather than a bare row because it is still a drop target for
        // dragging food between meals.
        return (
          <Card key={m.id} className={(me.length ? 'p-4' : 'px-4 py-2.5') + ' mb-3'} data-meal-drop={m.id} style={drag && dropAt && dropAt.mealId === m.id ? { outline: '4px solid var(--accent)', outlineOffset: '-4px', boxShadow: '4px 4px 0 0 var(--accent)' } : undefined}>
            <div className="flex justify-between items-start">
              <div className="flex items-center gap-1.5 min-w-0">
                <div className="flex flex-col -my-1 shrink-0">
                  <button onClick={() => moveMeal(m, -1)} disabled={mi === 0} style={{ opacity: mi === 0 ? 0.25 : 1 }} className="hit text-[#8A8A90] leading-none text-[10px] px-1 py-1.5" title="Move up">▲</button>
                  <button onClick={() => moveMeal(m, 1)} disabled={mi === meals.length - 1} style={{ opacity: mi === meals.length - 1 ? 0.25 : 1 }} className="hit text-[#8A8A90] leading-none text-[10px] px-1 py-1.5" title="Move down">▼</button>
                </div>
                {editMeal === m.id
                  ? <input autoFocus value={mealName} onChange={e => setMealName(e.target.value)} onBlur={() => { renameMeal(m, mealName); setEditMeal(null); }} onKeyDown={e => e.key === 'Enter' && e.currentTarget.blur()} className="bg-[#1E1E22] border border-[#262629] rounded-lg px-2 py-1 text-sm font-semibold w-40" />
                  : <button onClick={() => { setEditMeal(m.id); setMealName(m.name); }} className="hit font-semibold flex items-center gap-1.5 pt-0.5 min-w-0" title="Rename meal"><span className="truncate">{m.name}</span><span className="text-[#5A5A62] text-[11px] shrink-0">✎</span></button>}
              </div>
              <div className="flex items-start gap-1.5">
                {/* The meal's calories, and nothing else. Its protein/carbs/fat used to sit here in
                    three colours, which made the same breakdown appear at three levels on one
                    screen: the day card at the top, every meal header, and every food row. Only one
                    of those changes a decision, so the other two are ink without information.
                    (No meal-level Density Score either: it would sit on the day's per-calorie scale
                    while the blocks beside each food sit on the per-100 g one, so a meal holding one
                    food would disagree with the food inside it.) */}
                {/* An empty meal reads as an invitation, not a report. "0 kcal" is the lazy
                    placeholder the empty-state literature warns about: it states a fact nobody
                    needed and makes an ordinary mid-afternoon look like a failure. The dash is
                    quieter and truer, and the add action right below it is the way out. */}
                <div className="text-[12px] tnum text-right leading-tight pt-0.5" style={{ color: me.length ? 'var(--text2)' : 'var(--muted2)' }}>
                  {me.length ? Math.round(ms.kcal) + ' kcal' : '–'}
                </div>
                <div className="relative">
                  <button onClick={ev => { ev.stopPropagation(); setMenu(null); setMealMenu(mealMenu === m.id ? null : m.id); }} className="hit px-1 text-[#8A8A90]" aria-label="Meal options">⋯</button>
                  {mealMenu === m.id && <div className="absolute right-0 top-7 z-20 bg-[#1E1E22] border border-[#262629] rounded-2xl py-1 text-sm shadow-xl w-40" onClick={ev => ev.stopPropagation()}>
                    {me.length > 0 && <button onClick={() => saveMeal(m, me)} className="block w-full text-left px-4 py-2 hover:bg-[#262629]">Save as meal</button>}
                    {me.length > 0 && <button onClick={() => { setCopyTo({ title: 'Copy ' + m.name, entries: me, srcDate: date, pickMeal: true, meal: m.id }); setMealMenu(null); }} className="block w-full text-left px-4 py-2 hover:bg-[#262629]">Copy to…</button>}
                    {me.length > 0 && <button onClick={() => clearMeal(m, me)} className="block w-full text-left px-4 py-2 hover:bg-[#262629]">Clear food</button>}
                    <button onClick={() => { setMealMenu(null); setConfirm({ title: 'Delete ' + m.name + '?', body: me.length ? `Its ${me.length} logged item${me.length === 1 ? '' : 's'} will move to the meal above so nothing is lost. Only ${date === today ? 'today' : 'this day'} changes.` : `Removes this meal from ${date === today ? 'today' : 'this day'} only.`, confirmLabel: 'Delete meal', onConfirm: () => deleteMeal(m) }); }} className="block w-full text-left px-4 py-2 text-[#ff6b6b] hover:bg-[#262629]">Delete meal</button>
                  </div>}
                </div>
              </div>
            </div>
            {me.map(e => renderEntry(e, m, mc))}
            {drag && me.length === 0 && <div className="mt-2 py-4 text-center text-[11px] pf uppercase" style={{ color: 'var(--accent-ink)', border: '2px dashed var(--accent)' }}>Drop here</div>}
            {/* An empty meal is an invitation, not a report, so it gets the one thing you would want
                to do with it and no divider above it. A full meal keeps the rule, because there the
                button is separating the add action from a list of food. */}
            {/* The one action every meal card exists for, so it is sized like one. It used to be a
                19px-tall strip of text in an empty meal, under the 24px WCAG floor and a long way
                under the 44px anyone can actually hit; the row is full width and 44px tall in both
                states now, and only the divider still tells the two apart. */}
            <button onClick={() => openLog({ date, mealId: m.id })}
              className={'text-[13px] font-medium w-full text-left flex items-center ' + (me.length ? 'mt-2 pt-2 border-t border-[#262629]' : 'mt-1')}
              style={{ color: 'var(--accent-ink)', minHeight: 44 }}>+ Add food</button>
          </Card>);
      })}
      {(() => {
        const mealIds = new Set(meals.map(m => m.id));
        const orphans = day.filter(e => !mealIds.has(e.meal_id));
        if (!orphans.length) return null;
        const um = { id: '__unsorted__' };
        return (<Card className="p-4 mb-3" style={{ borderColor: 'var(--muted)' }}>
          <div className="flex justify-between items-center">
            <div className="font-semibold flex items-center gap-1.5" style={{ color: 'var(--muted)' }}>Unsorted</div>
            <div className="text-[11px] text-[#8A8A90] tnum">{Math.round(sumMacros(orphans).kcal)} kcal</div>
          </div>
          <div className="text-[11px] text-[#8A8A90] mt-1 mb-1">These were logged under a meal that isn't on this day. Drag each into a meal above.</div>
          {orphans.map(e => renderEntry(e, um, 'var(--muted)'))}
        </Card>);
      })()}
      </div>
      </div>
      {editing && (() => { const dc = dayContextFor(db, date, editing.id); const mm = meals.find(x => x.id === editing.meal_id);
        return <EditEntryModal entry={editing} onSave={saveEdit} onClose={() => setEditing(null)}
          onDelete={() => { del(editing); setEditing(null); }} contextLine={mm ? mm.name : null}
          onPhotoUpdate={E.photoUpdatable(editing) ? (() => { setPhotoUp(editing); setEditing(null); }) : null}
          dayRest={dc && dc.rest} dayTarget={dc && dc.target} />; })()}
      {photoUp && <PhotoUpdateSheet db={db} entry={photoUp} onSave={(item) => savePhotoUpdate(photoUp, item)} onClose={() => setPhotoUp(null)} />}
      {nameSheet && <NameSheet title="Save as meal" hint="Save this meal for one-tap logging. Name it:" initial={nameSheet.meal.name} saveLabel="Save meal" onSave={(name) => {
        const items = nameSheet.entries.map(e => ({ name: e.name, source: e.source, is_alcohol: e.is_alcohol, alcohol_split: e.alcohol_split, qtyLabel: e.qty_label, macros: e.computed_macros }));
        update(d => { d.saved_meals = (d.saved_meals || []).concat([{ id: Store.uid(), name, items, created_at: Date.now() }]); });
        setNameSheet(null); toast('Saved "' + name + '", find it under Meals when logging');
      }} onClose={() => setNameSheet(null)} />}
      {copyTo && <CopyToModal key={(copyTo.entries[0] ? copyTo.entries[0].id : '') + '|' + (copyTo.pickMeal ? 'm' : 'd') + '|' + copyTo.title} title={copyTo.title} srcDate={copyTo.srcDate} entries={copyTo.entries} loggedDates={logSet} meals={copyTo.pickMeal ? meals : null} defaultMeal={copyTo.meal} onPick={(t, mealId) => copyEntriesTo(copyTo.entries, t, mealId)} onClose={() => setCopyTo(null)} />}
      {confirm && <ConfirmDialog title={confirm.title} body={confirm.body} confirmLabel={confirm.confirmLabel} onConfirm={confirm.onConfirm} onClose={() => setConfirm(null)} />}
      {drag && ghost && (() => {
        const W = Math.min(320, (typeof window !== 'undefined' ? window.innerWidth : 360) - 40);
        return <div data-ghost className="fixed z-[80] pointer-events-none pixel-box" style={{ width: W, left: ghost.x - W + 14, top: ghost.y - 28, background: 'var(--card)', boxShadow: '5px 5px 0 0 var(--shadow)', transform: 'scale(1.02)', borderLeft: '4px solid ' + drag.mc, opacity: 0.97, pointerEvents: 'none' }}>
          <div className="flex items-center gap-3 py-2.5 px-2">
            <div className="w-9 h-9 pixel-box flex items-center justify-center shrink-0" style={{ background: drag.mc, boxShadow: 'none' }}><PixelGlyph kind={drag.kind} color="rgba(0,0,0,0.8)" size={20} /></div>
            <div className="min-w-0 flex-1">
              <div className="text-sm truncate">{drag.name}</div>
              <div className="flex items-center gap-1 text-[11px] tnum mt-0.5" style={{ color: 'var(--text2)' }}><PixelGlyph kind="scale" color="var(--muted)" size={11} />{drag.qty || '1 portion'}</div>
              <div className="text-[11px] tnum mt-0.5"><span className="font-bold" style={{ color: drag.mc }}>{drag.kcal}</span><span className="text-[#8A8A90]"> kc</span> <span style={{ color: PRO_T }}>{drag.p}P</span> <span style={{ color: CARB_T }}>{drag.c}C</span> <span style={{ color: FAT_T }}>{drag.f}F</span></div>
            </div>
            <span className="shrink-0 pr-1" style={{ color: drag.mc }}><PixelGrip /></span>
          </div>
        </div>;
      })()}
    </div>
  );
}
// Parse a stored qty label (e.g. "150 g", "2 cans", "1 can (500 ml)") back into amount + unit + noun.
function parseQty(label) {
  if (!label) return null;
  const m = String(label).trim().match(/^([0-9]*\.?[0-9]+|[¼½⅓⅔¾])\s*(.*)$/);
  if (!m) return null;
  const fracMap = { '¼': 0.25, '½': 0.5, '⅓': 1 / 3, '⅔': 2 / 3, '¾': 0.75 };
  const amt = fracMap[m[1]] != null ? fracMap[m[1]] : parseFloat(m[1]);
  if (!isFinite(amt) || amt <= 0) return null;
  const rest = (m[2] || '').trim();
  if (rest === '' || /^g\b/.test(rest) || rest === 'g') return { amount: amt, unit: 'g', noun: 'g' };
  if (/^oz\b/.test(rest)) return { amount: amt, unit: 'oz', noun: 'oz' };
  const noun = rest.replace(/s$/i, '') || 'serving';
  return { amount: amt, unit: 'serv', noun };
}
// Apply an entry edit: update the logged entry and carry the change back to the saved food so
// Recents re-adds with the latest details. Shared by the Food log editor and the post-log
// "Adjust" toast action.
function applyEntryPatch(update, id, patch) {
  update(d => {
    const x = d.log_entries.find(y => y.id === id); if (!x) return;
    x.name = patch.name; x.qty_label = patch.qty; x.computed_macros = patch.macros;
    if (patch.amount != null) x.amount = patch.amount; if (patch.unit) x.unit = patch.unit; if (patch.unit_noun) x.unit_noun = patch.unit_noun;
    if (patch.serving_g != null) x.serving_g = patch.serving_g; // keeps the grams/portions toggle available next time
    if (patch.alcohol_split !== undefined) x.alcohol_split = patch.alcohol_split;
    const key = patch.name.trim().toLowerCase(); const food = d.foods.find(y => y.name.trim().toLowerCase() === key && !!y.is_alcohol === !!x.is_alcohol);
    if (food) { food.macros = patch.macros; food.last_qty = patch.qty || food.last_qty; food.updated_at = Date.now(); if (patch.alcohol_split !== undefined) food.alcohol_split = patch.alcohol_split; }
  });
}
// Remember each AI-estimated component as a reusable, gram-scalable food, so it can be searched
// and re-logged at any weight later. Keyed by normalised name, so a single "225 g chicken"
// estimate enriches its own meal food rather than creating a duplicate. Shared by the first log of
// an estimate and by a later photo update of one, since both hand back the same breakdown.
function rememberEstimateItems(d, items) {
  (items || []).forEach(ri => {
    const g = +ri.grams || 0; if (g <= 0) return;
    const rk = (ri.name || '').trim().toLowerCase(); if (!rk) return;
    const per100 = { kcal: Math.round((+ri.kcal || 0) / g * 100), protein: +((+ri.protein || 0) / g * 100).toFixed(1), carbs: +((+ri.carbs || 0) / g * 100).toFixed(1), fat: +((+ri.fat || 0) / g * 100).toFixed(1), fiber: +((+ri.fiber || 0) / g * 100).toFixed(1) };
    let rf = d.foods.find(x => x.name.trim().toLowerCase() === rk && !x.is_alcohol);
    if (!rf) { rf = { id: Store.uid(), name: ri.name, source: 'ai_estimate', is_alcohol: false, is_favorite: false, last_qty: g + ' g', macros: { kcal: +ri.kcal || 0, protein: +ri.protein || 0, carbs: +ri.carbs || 0, fat: +ri.fat || 0, fiber: +ri.fiber || 0 }, updated_at: Date.now() }; d.foods.push(rf); }
    rf.corrected = true; rf.saved_base = per100; rf.saved_kind = 'per100'; rf.saved_serving_g = g; rf.saved_serving_label = ''; if (ri.nq) rf.nq = ri.nq; rf.updated_at = Date.now();
  });
}
/* Replace what a logged entry says with a fresh estimate made from a photo taken later.
   Deliberately NOT applyEntryPatch: that one edits an amount and leaves everything it was not told
   about alone, which is right for "make it 180 g" and wrong here. A meal re-estimated from a photo
   may no longer be counted in the unit the original was (200 g of chicken becomes "the whole
   meal"), so the unit fields are ASSIGNED rather than conditionally updated, including to
   undefined. Leaving a stale amount behind would make the edit sheet divide the new macros by the
   old weight and quietly show a tenth of the meal. */
function applyPhotoEstimate(update, id, item) {
  update(d => {
    const x = d.log_entries.find(y => y.id === id); if (!x) return;
    const macros = normalizeMacros(item.macros, x.is_alcohol);
    x.name = item.name || x.name;
    x.qty_label = item.qtyLabel || '';
    x.computed_macros = macros;
    x.amount = item.amount; x.unit = item.unit; x.unit_noun = item.unitNoun;
    x.serving_g = undefined;
    x.source = 'ai_estimate';
    // The nutrient record is what the Density Score reads. A re-estimate that came back without the
    // extra nutrients must not leave the OLD meal's score attached to the new numbers, so an
    // unscored estimate clears it and the day's backfill picks it up like any other unscored entry.
    x.nq = item.nq || null;
    x.photo_updated_at = Date.now();
    const key = (x.name || '').trim().toLowerCase();
    const food = key ? d.foods.find(y => y.name.trim().toLowerCase() === key && !!y.is_alcohol === !!x.is_alcohol) : null;
    if (food) { food.macros = macros; food.last_qty = x.qty_label || food.last_qty; if (item.nq) food.nq = item.nq; food.updated_at = Date.now(); }
    rememberEstimateItems(d, item.rememberItems);
  });
}
// Small in-app naming sheet (replaces window.prompt): prefilled text, Save/Cancel.
function NameSheet({ title, hint, initial, saveLabel, onSave, onClose }) {
  useBackClose(onClose);
  const [name, setName] = useState(initial || '');
  return (<div className="fixed inset-0 z-[70] bg-black/70 flex items-end sm:items-center justify-center" onClick={onClose}>
    <div className="bg-[#0F0F12] w-full max-w-md pixel-box p-5 sheet-up" style={{ paddingBottom: 'calc(1.75rem + env(safe-area-inset-bottom))' }} onClick={e => e.stopPropagation()}>
      <div className="flex justify-between items-center mb-3"><h2 className="text-lg font-semibold">{title}</h2><button onClick={onClose} className="w-11 h-11 flex items-center justify-center shrink-0 text-[#8A8A90] text-2xl leading-none">×</button></div>
      {hint && <div className="text-[12px] text-[#8A8A90] mb-3 leading-snug">{hint}</div>}
      <TextInput autoFocus value={name} onChange={e => setName(e.target.value)} onKeyDown={e => { if (e.key === 'Enter' && name.trim()) onSave(name.trim()); }} />
      <div className="flex gap-2 mt-4">
        <Btn kind="ghost" className="flex-1" onClick={onClose}>Cancel</Btn>
        <Btn kind="accent" className="flex-1" disabled={!name.trim()} style={{ opacity: name.trim() ? 1 : 0.5 }} onClick={() => onSave(name.trim())}>{saveLabel || 'Save'}</Btn>
      </div>
    </div>
  </div>);
}
/* Editing a logged food. This screen used to be strictly weaker than the confirm screen you get when
   ADDING one: no grams/portions toggle, no Density Score, no calorie sanity check, no way to delete
   the thing you were looking at. That is backwards, because the diary entry is the record that has
   to be right. It now shares the quantity control, the fraction chips and the day meter with the
   confirm screen, so a portion bug has one place to be fixed rather than two. */
function EditEntryModal({ entry, onSave, onClose, onDelete, onPhotoUpdate, title, saveVerb, contextLine, dayRest, dayTarget }) {
  useBackClose(onClose);
  const topRef = useScrolledToTop();
  const m = entry.computed_macros || {};
  const parsed = (entry.amount && +entry.amount > 0)
    ? { amount: +entry.amount, unit: entry.unit === 'g' || entry.unit === 'oz' ? entry.unit : 'serv', noun: entry.unit_noun || 'serving' }
    : parseQty(entry.qty_label);
  const amt0 = parsed ? parsed.amount : 1;
  const unit0 = parsed ? parsed.unit : 'serv';
  const noun = parsed ? parsed.noun : 'serving';
  const [name, setName] = useState(entry.name || '');
  // The name is the sheet's heading, not a permanent 54px text field at the top of it. Renaming a
  // logged food is rare, and charging the full price of an input for it on every single visit put
  // the thing you came to change below the fold.
  const [renaming, setRenaming] = useState(false);
  const [unit, setUnit] = useState(unit0);
  const [amount, setAmount] = useState(String(amt0));
  const [base, setBase] = useState({ protein: (m.protein || 0) / amt0, carbs: (m.carbs || 0) / amt0, fat: (m.fat || 0) / amt0, fiber: (m.fiber || 0) / amt0, kcal: (m.kcal || 0) / amt0 });
  const [edit, setEdit] = useState(false);
  // Grams per serving, recorded when the food was logged. Without it the two units cannot be
  // converted, so entries logged before this was stored keep the single unit they came with.
  const sg = +entry.serving_g || 0;
  const canSwitch = sg > 0 && unit !== 'oz';
  function switchUnit(u) {
    if (u === unit || !canSwitch) return;
    const toGrams = u === 'g';
    setBase(b => ({ protein: toGrams ? b.protein / sg : b.protein * sg, carbs: toGrams ? b.carbs / sg : b.carbs * sg, fat: toGrams ? b.fat / sg : b.fat * sg, fiber: toGrams ? b.fiber / sg : b.fiber * sg, kcal: toGrams ? b.kcal / sg : b.kcal * sg }));
    setAmount(x => String(Math.round(((+x || 0) * (toGrams ? sg : 1 / sg)) * 100) / 100));
    setUnit(u);
  }
  const a = +amount || 0;
  const total = { protein: +(base.protein * a).toFixed(1), carbs: +(base.carbs * a).toFixed(1), fat: +(base.fat * a).toFixed(1), fiber: +(base.fiber * a).toFixed(1), kcal: Math.round(base.kcal * a) };
  const step = unit === 'g' ? gramStep(a) : (a < 2 ? 0.25 : 1);
  const bump = (d) => setAmount(x => String(Math.max(0, +(((+x || 0) + d)).toFixed(2))));
  const setTotalField = (k, val) => { const v = +val || 0; setBase(b => Object.assign({}, b, { [k]: a > 0 ? v / a : v })); };
  const cap = (s) => String(s || '').charAt(0).toUpperCase() + String(s || '').slice(1);
  // A serving label can be a whole phrase ("portion (56 g)"). Beside a stepper there is room for a
  // word, so keep the head noun there and let the full phrase live on the unit toggle.
  const shortNoun = /[\s(]/.test(noun) ? (noun.split(/[\s(]/)[0] || 'serving') : noun;
  const plural = (+amount > 1 && /^[a-z]+$/i.test(noun)) ? 's' : '';
  const label = unit === 'g' ? `${fmtCount(amount)} g` : unit === 'oz' ? `${fmtCount(amount)} oz` : `${fmtCount(amount)} ${noun}${plural}`;
  // Alcohol calories carry no protein, they are split across carbs and fat. Let a logged drink's
  // split be re-balanced after the fact with a slider, keeping the calories fixed.
  const isAlc = !!entry.is_alcohol;
  const [carbPct, setCarbPct] = useState(() => (m.kcal > 0 ? Math.max(0, Math.min(100, Math.round(((m.carbs || 0) * 4 / m.kcal) * 10) * 10)) : 50));
  function setSplit(pct) { setCarbPct(pct); setBase(b => Object.assign({}, b, b.kcal > 0 ? { carbs: (b.kcal * pct / 100) / 4, fat: (b.kcal * (100 - pct) / 100) / 9 } : {})); }
  function save() { onSave({ name: name || entry.name, qty: label, macros: { kcal: total.kcal, protein: total.protein, carbs: total.carbs, fat: total.fat, fiber: total.fiber }, amount: a, unit, unit_noun: unit === 'g' ? 'g' : noun, serving_g: sg || undefined, alcohol_split: isAlc ? { carb_pct: carbPct, fat_pct: 100 - carbPct } : undefined }); }
  return (<div className="fixed inset-0 z-50 bg-black/70 flex items-end sm:items-center justify-center" onClick={onClose}>
    <div ref={topRef} className="bg-[#0F0F12] w-full max-w-md pixel-box p-5 max-h-[90vh] overflow-y-auto sheet-up" style={{ paddingBottom: 'calc(1.75rem + env(safe-area-inset-bottom))' }} onClick={e => e.stopPropagation()}>
      <div className="flex justify-between items-start gap-3 mb-4">
        <div className="min-w-0 flex-1">
          {renaming
            ? <TextInput autoFocus value={name} onChange={e => setName(e.target.value)} onBlur={() => setRenaming(false)}
                onKeyDown={e => { if (e.key === 'Enter') { e.preventDefault(); setRenaming(false); } }} aria-label="Name" />
            : <button onClick={() => setRenaming(true)} className="text-left w-full">
                {/* A dotted underline is the long-standing "you can change this in place" mark, so
                    the heading carries its own affordance and the line beneath it can go back to
                    saying something useful. It used to read "Breakfast · tap to rename", which is an
                    instruction manual printed on the furniture. */}
                <h2 className="text-lg font-semibold leading-tight" style={{ textDecoration: 'underline', textDecorationStyle: 'dotted', textDecorationColor: 'var(--muted)', textUnderlineOffset: 4 }}>{name || title || 'Edit food'}</h2>
                {contextLine && <div className="text-[11px] mt-1" style={{ color: 'var(--muted)' }}>{contextLine}</div>}
              </button>}
        </div>
        <button onClick={onClose} className="w-11 h-11 flex items-center justify-center shrink-0 text-[#8A8A90] text-2xl leading-none shrink-0" aria-label="Close">×</button>
      </div>
      {canSwitch && <div className="mb-3"><Seg value={unit === 'g' ? 'g' : 'serv'} onChange={switchUnit}
        options={[{ v: 'g', l: 'Grams' }, { v: 'serv', l: cap(shortNoun) + (sg ? ' (' + Math.round(sg) + ' g)' : '') }]} /></div>}
      <AmountField value={amount} onChange={e => setAmount(e.target.value)} unitLabel={unit === 'g' ? 'g' : unit === 'oz' ? 'oz' : shortNoun} step={step} onStep={bump} />
      {/* No preset buttons, for servings any more than for grams. Typing the number is one tap and
          a digit or two, and a rack of guesses at the amount only crowds the control that already
          answers the question exactly. */}
      {unit === 'g' && <div className="text-[11px] text-[#8A8A90] mt-1.5">±{step} g per tap</div>}
      <div className="pixel-box p-3 mt-3 mb-3" style={{ background: 'var(--surface3)', boxShadow: 'none' }}>
        <div className="flex justify-between items-baseline">
          <div className="tnum"><span className="text-xl font-bold" style={{ color: 'var(--text)' }}>{total.kcal}</span> <span className="text-[10px] text-[#8A8A90]">kcal</span></div>
          <div className="text-[12px] tnum"><span style={{ color: PRO_T }}>P{total.protein}</span> <span style={{ color: CARB_T }}>C{total.carbs}</span> <span style={{ color: FAT_T }}>F{total.fat}</span></div>
        </div>
        {/* The Density Score is invariant to how much you had (it is scored per 100 kcal), so the
            food's own score can be shown here without recomputing anything as the amount moves. */}
        {entry.nq && <div className="mt-2 pt-2" style={{ borderTop: '2px solid var(--surface2)' }}><DensityBadge nq={entry.nq} /></div>}
      </div>
      <DayImpact rest={dayRest} target={dayTarget} add={total} label={saveVerb === 'Add' ? 'Your day if you add this' : 'Your day if you save this'} />
      {isAlc && <div className="mb-3">
        <div className="pf text-[9px] uppercase text-[#8A8A90] mb-2">Split these calories</div>
        <Field label={`${carbPct}% carbs · ${100 - carbPct}% fat`}>
          <input type="range" min="0" max="100" step="10" value={carbPct} onChange={e => setSplit(+e.target.value)} className="w-full accent-[#4A9EEB]" />
          <div className="text-sm text-[#8A8A90] mt-2 tnum">= {total.carbs}g carbs · {total.fat}g fat</div>
        </Field>
      </div>}
      {/* Sits with "Numbers look off?" because it answers the same question, and above it because a
          photograph settles an amount better than typing a gram figure at it does. Only offered on
          entries where it means something: see Engine.photoUpdatable. */}
      {onPhotoUpdate && <button onClick={onPhotoUpdate} className="w-full flex items-center gap-2.5 mb-3 pixel-btn py-3 px-3 text-left" style={{ background: 'var(--surface3)' }}>
        <Icon.cam width="18" height="18" className="shrink-0" />
        <span className="min-w-0">
          <span className="block text-[13px] font-medium" style={{ color: 'var(--text)' }}>Update with a photo</span>
          {/* Once these numbers have come from a photo of the real plate they are no longer a
              forecast, and the pitch for re-doing it would be a lie. Say what happened instead. */}
          <span className="block text-[10.5px] leading-snug" style={{ color: 'var(--muted)' }}>{entry.photo_updated_at
            ? 'Already read from a photo of the real thing. Snap it again if this still looks wrong.'
            : 'Logged it before you ate it? Snap the real thing and the AI redoes the estimate.'}</span>
        </span>
      </button>}
      <Collapsible variant="inline" label="Numbers look off?" sub="Edit" className="mb-3">
      <div className="mb-2">
        <div className="grid grid-cols-3 gap-2.5"><Field label="Protein (g)"><NumInput value={total.protein} onChange={e => setTotalField('protein', e.target.value)} /></Field><Field label="Carbs (g)"><NumInput value={total.carbs} onChange={e => setTotalField('carbs', e.target.value)} /></Field><Field label="Fat (g)"><NumInput value={total.fat} onChange={e => setTotalField('fat', e.target.value)} /></Field></div>
        <div className="grid grid-cols-2 gap-2.5"><Field label="Fibre (g)"><NumInput value={total.fiber} onChange={e => setTotalField('fiber', e.target.value)} /></Field><Field label="Calories"><NumInput value={total.kcal} onChange={e => setTotalField('kcal', e.target.value)} /></Field></div>
      </div>
      </Collapsible>
      {/* The button says the number it is about to commit, so a mistyped amount gets one more chance
          to be caught on the control that commits it. Delete sits with the entry it deletes, instead
          of behind the ... menu on the row you have already left.
          It is NOT a red slab beside the yellow one. Two filled buttons of equal weight, one of them
          the loudest colour on the screen, is how a destructive action gets mistaken for the main
          one, and it sat a thumb's width from Save. The standard answer is a red LABEL rather than a
          red fill, set apart from the primary action instead of paired with it, which is also how
          the platform's own alerts do it. The undo toast is still the real safety net. */}
      <Btn kind="accent" className="w-full" disabled={a <= 0} style={{ opacity: a <= 0 ? 0.5 : 1 }} onClick={save}>{(saveVerb || 'Save') + ' ' + total.kcal + ' kcal'}</Btn>
      <div className="flex justify-between items-center mt-3">
        <TextBtn onClick={onClose} tone="quiet">Cancel</TextBtn>
        {onDelete && <TextBtn onClick={onDelete} tone="danger">Delete this entry</TextBtn>}
      </div>
    </div>
  </div>);
}

function CopyToModal({ title, srcDate, entries, loggedDates, meals, defaultMeal, onPick, onClose }) {
  useBackClose(onClose);
  const today = Store.todayISO();
  const [cm, setCm] = useState(() => { const d = new Date((srcDate || today) + 'T00:00:00'); return { y: d.getFullYear(), m: d.getMonth() }; });
  const [selMeal, setSelMeal] = useState(defaultMeal || (meals && meals[0] && meals[0].id));
  const first = new Date(cm.y, cm.m, 1); const startDow = (first.getDay() + 6) % 7;
  const daysIn = new Date(cm.y, cm.m + 1, 0).getDate();
  const cells = []; for (let i = 0; i < startDow; i++) cells.push(null);
  for (let dd = 1; dd <= daysIn; dd++) cells.push(Store.isoOf(new Date(cm.y, cm.m, dd)));
  const monthName = new Date(cm.y, cm.m, 1).toLocaleDateString('en-GB', { month: 'long', year: 'numeric' });
  const logged = loggedDates || new Set();
  // What's being copied, so the user has confidence before they pick a day.
  const count = (entries || []).length;
  const kcal = Math.round(sumMacros(entries || []).kcal);
  const pick = (c) => onPick(c, meals ? selMeal : undefined);
  // One-tap targets for the common cases, so most copies never touch the calendar.
  const quick = [{ iso: shiftISO(today, -1), label: 'Yesterday' }, { iso: today, label: 'Today' }, { iso: shiftISO(today, 1), label: 'Tomorrow' }];
  return (<div className="fixed inset-0 z-[60] bg-black/70 flex items-end sm:items-center justify-center" onClick={onClose}>
    <div className="bg-[#0F0F12] w-full max-w-md pixel-box p-5 max-h-[90vh] overflow-y-auto sheet-up" style={{ paddingBottom: 'calc(1.75rem + env(safe-area-inset-bottom))' }} onClick={e => e.stopPropagation()}>
      <div className="flex justify-between items-center mb-1"><h2 className="text-lg font-semibold truncate pr-2">{title}</h2><button onClick={onClose} className="w-11 h-11 flex items-center justify-center shrink-0 text-[#8A8A90] text-2xl leading-none shrink-0">×</button></div>
      {count > 0 && <div className="text-[11px] tnum mb-3" style={{ color: 'var(--text2)' }}>{count}{count === 1 ? ' item' : ' items'} <span className="text-[#5A5A62]">·</span> <span className="font-semibold" style={{ color: 'var(--accent-ink)' }}>{kcal}</span> kcal</div>}
      {meals && <div className="mb-3">
        <div className="pf text-[9px] uppercase text-[#8A8A90] mb-1.5">Into which meal</div>
        <div className="flex gap-1.5 flex-wrap">{meals.map(m => <button key={m.id} onClick={() => setSelMeal(m.id)} className={`pixel-box px-2.5 py-1.5 text-[11px] ${selMeal === m.id ? 'bg-white text-black font-bold' : 'bg-[#1E1E22] text-[#8A8A90]'}`} style={{ boxShadow: 'none' }}>{m.name}</button>)}</div>
      </div>}
      <div className="pf text-[9px] uppercase text-[#8A8A90] mb-1.5">Quick copy to</div>
      <div className="flex gap-1.5 mb-3">{quick.map(q => <button key={q.iso} onClick={() => pick(q.iso)} className={`flex-1 pixel-box px-2 py-2 text-[11px] font-bold ${q.iso === srcDate ? 'bg-[#262629] text-[#8A8A90]' : 'bg-[#1E1E22] text-white'}`} style={{ boxShadow: 'none' }}>{q.label}</button>)}</div>
      <div className="pf text-[9px] uppercase text-[#8A8A90] mb-1.5">Or pick a day</div>
      <div className="flex items-center justify-between mb-2">
        <button onClick={() => setCm(c => { const m = c.m - 1; return m < 0 ? { y: c.y - 1, m: 11 } : { y: c.y, m }; })} className="text-[#8A8A90] px-2 py-1">‹</button>
        <div className="text-sm font-semibold">{monthName}</div>
        <button onClick={() => setCm(c => { const m = c.m + 1; return m > 11 ? { y: c.y + 1, m: 0 } : { y: c.y, m }; })} className="text-[#8A8A90] px-2 py-1">›</button>
      </div>
      <div className="grid grid-cols-7 gap-1 text-center text-[10px] text-[#8A8A90] mb-1">{['M', 'T', 'W', 'T', 'F', 'S', 'S'].map((d, i) => <div key={i}>{d}</div>)}</div>
      <div className="grid grid-cols-7 gap-1">{cells.map((c, i) => c ? (
        <button key={i} onClick={() => pick(c)} className={`relative aspect-square text-[12px] tnum flex items-center justify-center pixel-box ${c === today ? 'bg-white text-black font-bold' : c === srcDate ? 'bg-[#262629] text-[#8A8A90]' : 'bg-[#1E1E22]'}`} style={{ boxShadow: 'none' }}>{new Date(c + 'T00:00:00').getDate()}{logged.has(c) && c !== today && <span className="absolute bottom-1 left-1/2 -translate-x-1/2 w-1 h-1" style={{ background: 'var(--accent)' }} />}</button>
      ) : <div key={i} />)}</div>
      <div className="flex items-center gap-1.5 mt-2 text-[10px] text-[#5A5A62]"><span className="inline-block w-1 h-1" style={{ background: 'var(--accent)' }} /> has food logged</div>
    </div>
  </div>);
}

/* =====================================================================
   LOG SHEET
   ===================================================================== */
// Unified "Food" tab: one search box over your own foods AND the Open Food Facts database, your
// recents/favourites when empty, saved meals, and a manual-entry fallback. Replaces the old
// separate Recent / Search / Meals / Manual tabs so logging is one clean screen.
// The day a sheet is logging into, with the entry being changed taken out of it, so the meter can
// show where you land BEFORE you commit rather than after you close the sheet. `excludeId` is the
// entry being edited: leaving it in would double-count it against its own replacement.
function dayContextFor(db, dateISO, excludeId) {
  if (!db || !dateISO) return null;
  const et = weekForecastTargets(db, [dateISO])[dateISO];
  if (!et || !et.eff) return null;
  const t = sumMacros(entriesOn(db, dateISO).filter(e => !excludeId || e.id !== excludeId));
  return {
    rest: { kcal: t.kcal, protein: t.protein, carbs: t.carbs, fat: t.fat },
    target: { kcal: et.eff.kcal, protein: et.eff.protein_g, carbs: et.eff.carbs_g, fat: et.eff.fat_g }
  };
}
/* ---------- UK food tables (CoFID) ----------------------------------------------------------
   Open Food Facts only knows things with a barcode on them. That left the most ordinary food
   there is with no right answer at all: search "chicken breast" and you got sliced deli meat,
   and anyone cooking from scratch was pushed to the AI estimator for a plain grilled chicken
   breast. This is CoFID (McCance & Widdowson's Composition of Foods Integrated Dataset, OHID,
   Open Government Licence v3.0), the UK reference for unpackaged food: 2,854 generic foods, half
   of them carrying the saturates, sugars and salt the Density Score needs, so a home-cooked meal
   can be scored from measured figures instead of an estimate. Regenerate with
   tools/build-generic-foods.py.
   Fetched on first use rather than inlined into the bundle: it is 219 KB (58 KB over the wire),
   the app shell is served network-first on every open, and plenty of sessions never search. */
let GENERIC_FOODS = null, GENERIC_LOAD = null;
function loadGenericFoods() {
  if (GENERIC_FOODS) return Promise.resolve(GENERIC_FOODS);
  if (!GENERIC_LOAD) {
    GENERIC_LOAD = fetch('/foods-uk.json')
      .then(r => r.ok ? r.json() : Promise.reject(new Error('http ' + r.status)))
      .then(d => {
        GENERIC_FOODS = (d.foods || []).map(f => {
          // CoFID is not on the UK label basis the rest of the app uses: its carbohydrate is
          // expressed as monosaccharide equivalents (about 7% high) and its energy gives fibre
          // 0 kcal. Convert at the boundary so a CoFID food and a barcoded product are directly
          // comparable in the same diary. See Cofid.toLabelBasis for the full reasoning.
          const lab = Cofid.toLabelBasis({ protein: f[2], carbs: f[3], fat: f[4], fiber: f[5], sugars: f[7] });
          return {
            name: f[0],
            per100: { kcal: lab.kcal, protein: lab.protein, carbs: lab.carbs, fat: lab.fat, fiber: lab.fiber },
            // Only hand over the density inputs when the food carries ALL of them, fibre included.
            // A null here means nobody measured it, which is not the same as none, and scoring an
            // unmeasured value as a virtuous zero is exactly how a food gets rated better than it is.
            extra: (f[5] != null && f[6] != null && f[7] != null && f[8] != null)
              ? { satfat: f[6], sugars: lab.sugars, salt: f[8] } : null,
            lc: f[0].toLowerCase()
          };
        });
        return GENERIC_FOODS;
      })
      .catch(e => { GENERIC_LOAD = null; throw e; });
  }
  return GENERIC_LOAD;
}
// CoFID names qualify from left to right ("Chicken, breast, grilled without skin, meat only"), so a
// match at the front of the name, and the shortest name among equals, is reliably the plainest form
// of the food. That puts "Chicken, breast, grilled without skin" above "Chicken and mushroom pie".
function searchGenericFoods(list, query, limit) {
  const terms = query.split(/\s+/).filter(Boolean);
  if (!terms.length) return [];
  const hits = [];
  for (let i = 0; i < list.length; i++) {
    const f = list[i];
    let ok = true;
    for (let t = 0; t < terms.length; t++) if (f.lc.indexOf(terms[t]) < 0) { ok = false; break; }
    if (!ok) continue;
    const at = f.lc.indexOf(terms[0]);
    const rank = at === 0 ? 0 : (/[\s,(]/.test(f.lc.charAt(at - 1)) ? 1 : 2);
    hits.push({ f: f, k: rank * 10000 + f.name.length });
  }
  hits.sort((a, b) => a.k - b.k);
  return hits.slice(0, limit || 12).map(x => x.f);
}
/* ---------- Grounding an AI estimate against CoFID -------------------------------------------
   The matching, tolerances and comparison live in app/cofid.js (pure, unit-tested in
   tests/cofid.test.js). searchGenericFoods is injected rather than imported, because the ranking a
   match depends on is the app's own food search. */
function cofidCheck(list, items) { return Cofid.check(searchGenericFoods, list, items); }
